    [4854] = {
        achievementId = 4854,
        name = "I Had It in My Hand",
        category = "Professions",
        sourceType = "Achievement",
        source = "I Had It in My Hand",
        difficulty = "medium",
        difficultyReason = "Rare projects are randomly offered after other projects; multiple cultures reduce reliance on one rare drop.",
        acquisition = "Difficulty: Medium - Rare projects are randomly offered after other projects; multiple cultures reduce reliance on one rare drop.\n\n1. Learn Archaeology from Harrison Jones in Stormwind's library (85.6, 25.8) or Belloc Brightblade in Orgrimmar (49.0, 70.6). Enable Archaeology dig sites on the world map. Dig sites are personal and move as YOU finish them; another player's route does not determine your active sites.\n\n2. At an active dig site, stand inside its highlighted boundary and use Survey. Follow the instrument's direction: red means far away, yellow closer, green nearby. Survey again until the fragment object appears, then LOOT it. Continue until the site disappears and a replacement spawns. Clearing unwanted races also frees slots for the race you need.\n\n3. Open Archaeology, select the race whose fragments you collected, and complete its CURRENT research project when you have enough fragments. Insert matching keystones where the project has sockets to reduce its cost. The next project is random: you cannot select an unsolved artifact directly.\n\n4. When a BLUE-quality rare project appears, collect its required fragments and FINISH that solve. Merely revealing the project is insufficient. Complete 1 DIFFERENT rare projects; extra copies or appearance collection from another source do not replace the Archaeology solve.\n\n5. Work across cultures rather than waiting only for one very rare Tol'vir weapon. Fossil and Night Elf sites in Kalimdor, Dwarf/Troll in Eastern Kingdoms, Orc/Draenei in Outland and Vrykul/Nerubian in Northrend all provide eligible rares. Later-expansion Archaeology rares can contribute too.\n\n6. Optional at Archaeology 600: solve common Pandaria artifacts, crate the completed objects into Restored Artifacts, then exchange them with Brann at the Seat of Knowledge (83.5, 31.0 above Mogu'shan Palace) for the old race's fragments. Crates supply fragments, not a guaranteed rare project. Original Eastern Kingdoms/Kalimdor gray artifacts cannot be crated this way.\n\n7. Check the live rare-project counter after each completed rare. Return to races with missing projects until it reaches 1; there is no fixed number of digs or guaranteed completion time.",
        stepCount = 7,
        waypoints = {
            { mapID = 84, x = 0.856, y = 0.258, step = 1, label = "Harrison Jones - Archaeology trainer" },
            { mapID = 85, x = 0.49, y = 0.706, step = 1, label = "Belloc Brightblade - Archaeology trainer" },
            { mapID = 390, x = 0.835, y = 0.31, step = 6, label = "Brann - optional restored-artifact fragment exchange" },
        },
        areaMaps = { 13, 12, 101, 113 },
        sources = {
            "https://www.wowhead.com/achievement=4854#comments:id=5813873",
            "https://www.wowhead.com/achievement=4856#comments:id=1339634",
