    [4858] = {
        achievementId = 4858,
        name = "Seven Scepters",
        category = "Professions",
        sourceType = "Achievement",
        source = "Seven Scepters",
        difficulty = "hard",
        difficultyReason = "Seven named common artifacts spread across five cultures and three continents.",
        acquisition = "Difficulty: Hard - Seven named common artifacts spread across five cultures and three continents.\n\n1. Learn Archaeology from Harrison Jones in Stormwind's library (85.6, 25.8) or Belloc Brightblade in Orgrimmar (49.0, 70.6). Enable Archaeology dig sites on the world map. Dig sites are personal and move as YOU finish them; another player's route does not determine your active sites.\n\n2. Reach at least Archaeology 375 for Northrend access. Track the seven named criteria; collecting a similarly named equipped weapon is not a research solve.\n\n3. In Eastern Kingdoms, solve DWARF projects for Scepter of Bronzebeard and Scepter of Charlga Razorflank, and TROLL projects for Atal'ai Scepter. Clear unwanted sites to rotate the continent's active locations.\n\n4. In Kalimdor, solve NIGHT ELF projects for Scepter of Xavius. There is no need to enter an Emerald Nightmare raid or defeat Xavius.\n\n5. In OUTLAND, solve DRAENEI projects for Scepter of the Nathrezim and ORC projects for Scepter of Nekros Skullcrusher. Use the original Outland map, not Draenor.\n\n6. In Northrend, solve NERUBIAN projects for Scepter of Nezar'Azret. If your active sites are all other cultures, finish them to roll replacements.\n\n7. At Archaeology 600, Brann's Restored Artifact exchanges above Mogu'shan Palace can supply the missing race's fragments instead of direct digging. Solve every offered common until all seven named scepters are recorded. The rare Scepter of Azj'Aqir is NOT required.",
        stepCount = 7,
        waypoints = {
            { mapID = 84, x = 0.856, y = 0.258, step = 1, label = "Harrison Jones - Archaeology trainer" },
