    [4868] = {
        achievementId = 4868,
        name = "Cataclysm Explorer",
        category = "Exploration",
        sourceType = "Achievement",
        source = "Cataclysm Explorer",
        difficulty = "medium",
        difficultyReason = "Explore five zones, including all three Vashj'ir submaps.",
        acquisition = "Difficulty: Medium - Explore five zones, including all three Vashj'ir submaps.\n\n1. Complete Explore Hyjal (4863) using its eleven-location route. Use outdoor Mount Hyjal, not the Battle for Mount Hyjal raid.\n\n2. Complete Explore Deepholm (4864), flying the outer ring from the Temple of Earth.\n\n3. Complete Explore Twilight Highlands (4866), including the often-missed Krazzworks, Crucible of Carnage, Highland Forest and Gullet.\n\n4. Complete Explore Vashj'ir (4825) across Kelp'thar Forest, Shimmering Expanse and Abyssal Depths. Select the correct water-zone map for each guide coordinate.\n\n5. Complete Explore Uldum (4865) in Zidormi's earlier phase. Check all five component achievements; Surveying the Damage and the old-world zone explorations are separate objectives.",
