    [4869] = {
        achievementId = 4869,
        name = "Sinking into Vashj'ir",
        category = "Quests",
        sourceType = "Achievement",
        source = "Sinking into Vashj'ir",
        faction = "Alliance",
        difficulty = "medium",
        difficultyReason = "Complete several connected quest chapters, including their prerequisite hand-ins.",
        acquisition = "Difficulty: Medium - Complete several connected quest chapters, including their prerequisite hand-ins.\n\n1. Enable Trivial Quests on the minimap and track this achievement's CURRENT named chapters. Old comments' numeric quest totals predate storyline tracking. Turn in each branch's final quest and take its follow-up before leaving the hub. Begin Call of Duty from your faction's Vashj'ir introduction: Stormwind Harbor for Alliance or Commander Thorak on Durotar's eastern shore for Horde. Stay for the quest ship/event. Complete Sea Legs immediately after the shipwreck.\n\n2. In Kelp'thar Forest, complete your faction's wreck defense, then Moanah's Better Late Than Dead / The Abyssal Ride to obtain the seahorse. Continue the Smuggler's Scar cave quests and Budd's shark/pearl expedition. Loot quest-starting maps and accept any automatic follow-up in the quest tracker.\n\n3. Follow Across the Great Divide into Shimmering Expanse. Complete Silver Tide Hollow, Toshe's naga assault and Nespirah's rescue chain through Waking the Beast. Cave entrances are underwater; look for the large plants outside them instead of swimming directly into solid rock above a map marker.\n\n4. Follow The Call of the Blade / Upon the Scene of Battle and complete ALL THREE Battlemaiden vision chains, returning to the present and handing in between them. Their final quests are Not Soon Forgotten, The Culmination of Our Efforts and Final Judgement. Use the separate Visions of Vashj'ir Past guide for the vehicle sequence.\n\n5. Continue A Breath of Fresh Air and Full Circle into the Abyssal Depths. Finish the Earthen Ring's ancient/Neptulon campaign through Defending the Rift. Your faction's hub differs, but both continue through L'ghorek and the final scripted transport; a Throne of the Tides dungeon clear does not replace the story.\n\n6. Check every zone-story chapter. If a chapter is missing, resume that specific wreck, cave, vision or ancient branch. Do not farm random underwater kills for an old 130/140-quest total; the chapters now determine completion.",
        stepCount = 6,
        waypoints = {
            { mapID = 201, x = 0.4, y = 0.3, step = 1, label = "Kelp'thar Forest - shipwreck campaign start" },
            { mapID = 201, x = 0.58, y = 0.78, step = 2, label = "The Clutch - continue toward the Expanse" },
            { mapID = 205, x = 0.5, y = 0.41200000000000003, step = 3, label = "Silver Tide Hollow - cave hub" },
            { mapID = 205, x = 0.51, y = 0.48, step = 3, label = "Nespirah - rescue storyline" },
            { mapID = 205, x = 0.505, y = 0.764, step = 4, label = "Biel'aran Ridge - Battlemaiden story" },
            { mapID = 204, x = 0.35, y = 0.52, step = 5, label = "L'ghorek - ancient / Neptulon storyline" },
        },
        areaMaps = { 201, 205, 204 },
        sources = {
