    [4875] = {
        achievementId = 4875,
        name = "Loremaster of Cataclysm",
        category = "Quests",
        sourceType = "Achievement",
        source = "Loremaster of Cataclysm",
        difficulty = "medium",
        difficultyReason = "Complete several connected quest chapters, including their prerequisite hand-ins.",
        acquisition = "Difficulty: Medium - Complete several connected quest chapters, including their prerequisite hand-ins.\n\n1. Complete Coming Down the Mountain in Mount Hyjal. Finish its Aviana hatchery and Sanctuary follow-ups as well as the southern finale; a Molten Front daily unlock alone does not complete all nine Hyjal chapters.\n\n2. Complete Deep into Deepholm through Mending the Wound. Use its individual guide for the easily missed Close Escort and Twilight Research leads if the World Pillar story stops.\n\n3. Complete Unearthing Uldum in Zidormi's earlier phase. Finish BOTH Ramkahen's royal-family campaign and Harrison's expedition, including the scarab-triggered Just a Fancy Cockroach quest.\n\n4. Complete your faction's Fading into Twilight. Start through the current capital introduction so the landing base and later branches unlock, then finish its actual named chapter list.\n\n5. Complete your faction's Sinking into Vashj'ir across Kelp'thar Forest, Shimmering Expanse and Abyssal Depths. Follow its individual campaign guide through the visions and final Rift defense; this is the FIFTH required zone.\n\n6. Check all five component achievements. Completed components can contribute across eligible characters; each new character still needs its own quest prerequisites. The redesigned Eastern Kingdoms/Kalimdor zone stories belong to their separate continent metas.",
        stepCount = 6,
        waypoints = {
            { mapID = 198, x = 0.62, y = 0.25, step = 1, label = "Mount Hyjal - Nordrassil" },
