    [4881] = {
        achievementId = 4881,
        name = "The Earthen Ring",
        category = "Reputation",
        sourceType = "Achievement",
        source = "The Earthen Ring",
        difficulty = "medium",
        difficultyReason = "Unlock the Friendly tabard and earn Exalted through quests and eligible dungeon kills.",
        acquisition = "Difficulty: Medium - Unlock the Friendly tabard and earn Exalted through quests and eligible dungeon kills.\n\n1. Complete Earthen Ring quests in Vashj'ir and Deepholm to reach Friendly. Arok is in Silver Tide Hollow, an air-filled cave in Shimmering Expanse; approach through the underwater cave entrance, not the surface directly above the pin.\n\n2. At FRIENDLY, visit Provisioner Arok at the marked location and buy Tabard of the Earthen Ring. EQUIP it before entering a reputation-granting dungeon.\n\n3. Use an original Cataclysm dungeon such as NORMAL Lost City of the Tol'vir in Uldum. Kill reputation-granting trash and bosses and inspect the reputation log to confirm the equipped tabard is awarding The Earthen Ring. This avoids the seasonal Mythic reworks of other old dungeons.\n\n4. Leave, reset the Normal instance and repeat within the game's entry limit, keeping the tabard equipped. A killed Heroic boss uses its daily lockout and Reset All Instances cannot restore it. Complete unlocked faction quests/dailies as an alternative while travelling.\n\n5. Stop at EXALTED and check the achievement. Buying a tabard or a reputation reward alone does not finish the reputation bar, and a later expansion's tabard converts reputation to a different faction.",
        stepCount = 5,
        waypoints = {
            { mapID = 205, x = 0.49, y = 0.42, step = 2, label = "Provisioner Arok - The Earthen Ring tabard" },
            { mapID = 249, x = 0.605, y = 0.644, step = 3, label = "Lost City of the Tol'vir - Normal championing route" },
        },
        sources = {
