    [4914] = {
        achievementId = 4914,
        name = "Working In the Heat",
        category = "Professions",
        sourceType = "Achievement",
        source = "Working In the Heat",
        difficulty = "medium",
        difficultyReason = "Level the Cataclysm branch of 2 primary profession(s), not a later expansion's branch.",
        acquisition = "Difficulty: Medium - Level the Cataclysm branch of 2 primary profession(s), not a later expansion's branch.\n\n1. Choose 2 PRIMARY profession(s) on the character. Ask a Stormwind or Orgrimmar guard for each trainer, learn that profession and specifically learn its CATACLYSM category. Cooking, Fishing and Archaeology do not count as primary professions.\n\n2. Open the Cataclysm skill bar. For crafting, learn orange/yellow recipes, obtain the listed Cataclysm materials and make those recipes until they stop giving reliable skill, then learn the next recipes. For gathering, gather appropriate Cataclysm herbs, ore or skins in Hyjal, Deepholm, Uldum or Twilight Highlands.\n\n3. Reach SEVENTY-FIVE base Cataclysm skill in 2 primary profession(s). Check earned skill rather than counting a racial or equipment bonus. The old generic 525 requirement became a separate Cataclysm 1-75 bar.\n\n4. Verify the live achievement before changing a profession. For Working In the Heat, keep both completed primary professions together; a Cooking bar plus one primary profession is insufficient.",
        stepCount = 4,
        waypoints = {},
        areaMaps = { 84, 85, 198, 207, 249, 241 },
        sources = {
            "https://www.wowhead.com/achievement=4914#comments:id=1265488",
            "https://www.wowhead.com/achievement=4924#comments:id=1242523",
        },
        reviewedAt = "2026-11-05",
        wowheadUrl = "https://www.wowhead.com/achievement=4914",
        sourceURL = "https://www.wowhead.com/achievement=4914#comments",
    },
    [4916] = {
        achievementId = 4916,
        name = "Cataclysmic Cook",
        category = "Professions",
        sourceType = "Achievement",
        source = "Cataclysmic Cook",
        difficulty = "medium",
        difficultyReason = "Train and level the separate Cataclysm Cooking bar to 75.",
        acquisition = "Difficulty: Medium - Train and level the separate Cataclysm Cooking bar to 75.\n\n1. Visit Stephen Ryback in Stormwind (76.8, 53.6) or Zamja in Orgrimmar (32.2, 69.6). Learn Cooking and its CATACLYSM category, then select that category in the profession window.\n\n2. Begin with the trainer's Cataclysm recipes such as Blackened Surprise using Toughened Flesh. Cook orange or yellow recipes beside a fire and learn the next available recipes as the earlier ones turn green or gray.\n\n3. For the later recipes, complete a capital Cooking daily for Epicurean's Awards and buy Cataclysm recipes from the nearby sous-chef vendor. Obtain the exact Cataclysm fish or meat from the Auction House or the zones named in the recipe. More copies of a gray low-level recipe cannot finish the skill bar reliably.\n\n4. Reach 75 BASE Cataclysm Cooking and check the achievement. Halfhill's old fast 1-525 instructions predate the expansion skill split; Pandaria Cooking skill does not replace Cataclysm Cooking.",
