    [4917] = {
        achievementId = 4917,
        name = "Cataclysmic Fisherman",
        category = "Professions",
        sourceType = "Achievement",
        source = "Cataclysmic Fisherman",
        difficulty = "easy",
        difficultyReason = "Learn Cataclysm Fishing, then fish repeatedly in Hyjal waters.",
        acquisition = "Difficulty: Easy - Learn Cataclysm Fishing, then fish repeatedly in Hyjal waters.\n\n1. Learn Fishing and CATACLYSM Fishing from a trainer offering that expansion branch, such as Old Umbehto in Orgrimmar (35.0, 67.5) or Arnold Leland in Stormwind (55.0, 69.6). Confirm that Cataclysm Fishing appears in the profession window before travelling.\n\n2. Take the capital's Cataclysm portal to Mount Hyjal. Go to the small lake behind Nordrassil's portal/building and cast into its open water. Wait for the bobber, click it and loot the catch.\n\n3. Keep fishing until the Cataclysm bar reaches SEVENTY-FIVE. Gains become less frequent; a fishing pole or lure's bonus is not earned base skill. Check the achievement after the final gain. You do not need a rare fish, a pool or an old 525 overall skill bar.",
        stepCount = 3,
        waypoints = {
            { mapID = 84, x = 0.55, y = 0.696, step = 1, label = "Arnold Leland - Fishing training" },
            { mapID = 85, x = 0.35, y = 0.675, step = 1, label = "Old Umbehto - Cataclysm Fishing training" },
        },
        areaMaps = { 198 },
