    [4919] = {
        achievementId = 4919,
        name = "Expert Archaeologist",
        category = "Professions",
        sourceType = "Achievement",
        source = "Expert Archaeologist",
        difficulty = "medium",
        difficultyReason = "Surveying and completed projects raise the persistent Archaeology skill.",
        acquisition = "Difficulty: Medium - Surveying and completed projects raise the persistent Archaeology skill.\n\n1. Learn Archaeology from Harrison Jones in Stormwind's library (85.6, 25.8) or Belloc Brightblade in Orgrimmar (49.0, 70.6). Enable Archaeology dig sites on the world map. Dig sites are personal and move as YOU finish them; another player's route does not determine your active sites.\n\n2. At an active dig site, stand inside its highlighted boundary and use Survey. Follow the instrument's direction: red means far away, yellow closer, green nearby. Survey again until the fragment object appears, then LOOT it. Continue until the site disappears and a replacement spawns. Clearing unwanted races also frees slots for the race you need.\n\n3. Open Archaeology, select the race whose fragments you collected, and complete its CURRENT research project when you have enough fragments. Insert matching keystones where the project has sockets to reduce its cost. The next project is random: you cannot select an unsolved artifact directly.\n\n4. Continue completing research projects until your BASE Archaeology skill reaches 225. Surveying stops giving early skill gains, so do not keep digging while leaving every project unsolved. Old advice to save all solves for the original 525 cap is optional, not an achievement requirement.\n\n5. You can remain in Eastern Kingdoms or Kalimdor for this target. At 300 skill Outland becomes available, at 375 Northrend, and at 450 Tol'vir sites in original Uldum. Check the skill and achievement after a solve; racial bonuses are not earned skill points.",
        stepCount = 5,
        waypoints = {
            { mapID = 84, x = 0.856, y = 0.258, step = 1, label = "Harrison Jones - Archaeology trainer" },
            { mapID = 85, x = 0.49, y = 0.706, step = 1, label = "Belloc Brightblade - Archaeology trainer" },
        },
        areaMaps = { 13, 12 },
        sources = { "https://www.wowhead.com/achievement=4919#comments:id=1756818" },
