    [4924] = {
        achievementId = 4924,
        name = "Professional Cataclysmic Master",
        category = "Professions",
        sourceType = "Achievement",
        source = "Professional Cataclysmic Master",
        difficulty = "medium",
        difficultyReason = "Level the Cataclysm branch of 1 primary profession(s), not a later expansion's branch.",
        acquisition = "Difficulty: Medium - Level the Cataclysm branch of 1 primary profession(s), not a later expansion's branch.\n\n1. Choose 1 PRIMARY profession(s) on the character. Ask a Stormwind or Orgrimmar guard for each trainer, learn that profession and specifically learn its CATACLYSM category. Cooking, Fishing and Archaeology do not count as primary professions.\n\n2. Open the Cataclysm skill bar. For crafting, learn orange/yellow recipes, obtain the listed Cataclysm materials and make those recipes until they stop giving reliable skill, then learn the next recipes. For gathering, gather appropriate Cataclysm herbs, ore or skins in Hyjal, Deepholm, Uldum or Twilight Highlands.\n\n3. Reach SEVENTY-FIVE base Cataclysm skill in 1 primary profession(s). Check earned skill rather than counting a racial or equipment bonus. The old generic 525 requirement became a separate Cataclysm 1-75 bar.\n\n4. Verify the live achievement before changing a profession. For Working In the Heat, keep both completed primary professions together; a Cooking bar plus one primary profession is insufficient.",
        stepCount = 4,
        waypoints = {},
        areaMaps = { 84, 85, 198, 207, 249, 241 },
        sources = {
            "https://www.wowhead.com/achievement=4914#comments:id=1265488",
            "https://www.wowhead.com/achievement=4924#comments:id=1242523",
        },
        reviewedAt = "2026-11-05",
        wowheadUrl = "https://www.wowhead.com/achievement=4924",
        sourceURL = "https://www.wowhead.com/achievement=4924#comments",
    },
    [4925] = {
        achievementId = 4925,
        name = "Ashenvale Quests",
        category = "Quests",
        sourceType = "Achievement",
        source = "Ashenvale Quests",
        faction = "Alliance",
        difficulty = "medium",
        difficultyReason = "Complete several connected quest chapters, including their prerequisite hand-ins.",
        acquisition = "Difficulty: Medium - Complete several connected quest chapters, including their prerequisite hand-ins.\n\n1. Enable Trivial Quests on the minimap and track this achievement's CURRENT named chapters. Old comments' numeric quest totals predate storyline tracking. Turn in each branch's final quest and take its follow-up before leaving the hub. Start the Alliance campaign at Maestra's Post/Astranaar and follow its hand-offs south to Stardust Spire.\n\n2. Complete Maestra's Post, Saving Astranaar and The Power of Dartol's Rod. Follow the rod's quest interactions through the furbolg story rather than treating a random furbolg kill as the chapter's completion.\n\n3. At Stardust Spire, finish the gnome rescue and local assault quests, then follow the elemental harmony and corrupted-heart branches into the forest. The Satyrnaar chain is another named chapter; do not leave it after only the first satyr objective.\n\n4. Loot quest starters while working the relevant areas, including Troll Charm and Diabolical Plans if they open a missing branch. Check the seven current chapter names; the old seventy-quest target is obsolete.\n\n5. Check the remaining named chapters, return to their own hub and finish their hand-ins. A quest marker can be inside a building, on an object or just over the adjoining zone border. Unrelated dungeon quests, repeatable reputation turn-ins and an old total such as 60/60 do not substitute for the current story criteria.",
        stepCount = 5,
        waypoints = {
            { mapID = 63, x = 0.27, y = 0.36, step = 2, label = "Maestra's Post" },
            { mapID = 63, x = 0.36, y = 0.5, step = 2, label = "Astranaar - defense and Dartol branch" },
            { mapID = 63, x = 0.35, y = 0.72, step = 3, label = "Stardust Spire - rescue / campaign continuation" },
            { mapID = 63, x = 0.81, y = 0.49, step = 3, label = "Satyrnaar - satyr storyline" },
        },
        sources = { "https://www.wowhead.com/achievement=4925#comments:id=1186962" },
        reviewedAt = "2026-11-10",
        wowheadUrl = "https://www.wowhead.com/achievement=4925",
        sourceURL = "https://www.wowhead.com/achievement=4925#comments",
    },
    [4926] = {
        achievementId = 4926,
        name = "Bloodmyst Isle Quests",
        category = "Quests",
        sourceType = "Achievement",
        source = "Bloodmyst Isle Quests",
        faction = "Alliance",
        difficulty = "medium",
        difficultyReason = "Complete several connected quest chapters, including their prerequisite hand-ins.",
        acquisition = "Difficulty: Medium - Complete several connected quest chapters, including their prerequisite hand-ins.\n\n1. Enable Trivial Quests on the minimap and track this achievement's CURRENT named chapters. Old comments' numeric quest totals predate storyline tracking. Turn in each branch's final quest and take its follow-up before leaving the hub. Begin at Blood Watch and follow its Triumvirate quests. If a required Bloodcurse lead is missing, return to Admiral Odesyus in southern Azuremyst rather than searching only Bloodmyst.\n\n2. Finish the three separate Triumvirate branches from Boros, Kuros and Aesom. Talk to Boros even if he displays the repeatable Irradiated Crystal Shards marker; he can also have ordinary story quests behind that repeatable interaction.\n\n3. Complete Galaen's Fate and the Loreth'Aran ruins storyline, then the Bloodcurse chain. Check Messenger Hermesius at Blood Watch and Odesyus's The Bloodcurse Legacy lead on Azuremyst if the Bloodcurse chapter never opened.\n\n4. Continue Vindicator's Rest's defensive assault and The Unwritten Prophecy finale. Loot relevant quest starters, including Cruelfin's pendant/Tzerak's armor plate when they open unfinished branches. An old sixty/sixty-five quest list is not the current eight-chapter checklist.\n\n5. Check the remaining named chapters, return to their own hub and finish their hand-ins. A quest marker can be inside a building, on an object or just over the adjoining zone border. Unrelated dungeon quests, repeatable reputation turn-ins and an old total such as 60/60 do not substitute for the current story criteria.",
        stepCount = 5,
        waypoints = {
            { mapID = 106, x = 0.55, y = 0.55, step = 2, label = "Blood Watch - three Triumvirate branches" },
            { mapID = 106, x = 0.61, y = 0.44, step = 3, label = "Loreth'Aran - ruins story" },
            { mapID = 97, x = 0.47, y = 0.7, step = 3, label = "Odesyus' Landing - Bloodcurse prerequisite" },
            { mapID = 106, x = 0.31, y = 0.47, step = 4, label = "Vindicator's Rest - final defensive campaign" },
        },
        sources = {
