    [4956] = {
        achievementId = 4956,
        name = "5 Dungeon Quests Completed",
        category = "Quests",
        sourceType = "Achievement",
        source = "5 Dungeon Quests Completed",
        difficulty = "easy",
        difficultyReason = "Complete dungeon QUEST hand-ins, rather than simply killing dungeon bosses.",
        acquisition = "Difficulty: Easy - Complete dungeon QUEST hand-ins, rather than simply killing dungeon bosses.\n\n1. Track the achievement and enable Trivial Quests on your minimap. Choose a character with unfinished dungeon quests. A boss kill or dungeon-completion achievement without a quest hand-in does not add to this total.\n\n2. For a compact first five, enter NORMAL Deadmines through Moonbrook, Westfall. Speak to the faction questgiver just inside, by the teleporter in the next room, and accept the first quest before moving to Glubtok.\n\n3. Complete and TURN IN each quest after its corresponding boss, then accept the next before continuing through Helix, Foe Reaper, Ripsnarl and Cookie. The Alliance chain is quests 27756, 27758, 27781, 27785 and 27790; Horde uses 27842, 27844, 27847, 27848 and 27850. Turn in the Cookie quest at the end for five hand-ins.\n\n4. Check that five dungeon quests are recorded. If this character already finished that chain, use other unfinished dungeon quests instead; repeating the boss kills does not reset completed one-time quests.",
        stepCount = 4,
        waypoints = {
            { mapID = 52, x = 0.426, y = 0.7170000000000001, step = 2, label = "Moonbrook - Deadmines entrance below town" },
