    [4958] = {
        achievementId = 4958,
        name = "The First Rule of Ring of Blood is You Don't Talk About Ring of Blood",
        category = "Quests",
        sourceType = "Achievement",
        source = "The First Rule of Ring of Blood is You Don't Talk About Ring of Blood",
        difficulty = "easy",
        difficultyReason = "Three short arena quest chains, with travel between three expansions.",
        acquisition = "Difficulty: Easy - Three short arena quest chains, with travel between three expansions.\n\n1. Use ONE character for all three arena chains; a later Retail comment reports that splitting them across alts does not complete the meta. Enable Trivial Quests and track its three named criteria.\n\n2. OUTLAND NAGRAND: speak to Gurgthock at the Ring of Blood near 42.8,20.7, north of the Laughing Skull Ruins. Accept each arena challenge, defeat its summoned opponent and turn it in before taking the next. Continue through The Ring of Blood: The Final Challenge and Mogor.\n\n3. NORTHREND ZUL'DRAK: visit Gurgthock at the Amphitheater of Anguish near 48.4,56.4. Complete the full sequence, accepting the next fight between opponents, through The Champion of Anguish. Wait for another group's event to finish if the goblin is busy.\n\n4. TWILIGHT HIGHLANDS: visit Gurgthock at the Crucible of Carnage around 50,58. Finish every offered arena challenge through The Crucible of Carnage: The Twilight Terror! and turn in the final quest. This also completes Round Three. Fight!.\n\n5. Check all THREE criteria after the final hand-in. Do not substitute Draenor's Nagrand arena, the Ring of Trials, an arena PvP match or a later expansion's arena chain.",
        stepCount = 5,
        waypoints = {
            { mapID = 107, x = 0.428, y = 0.207, step = 2, label = "Outland - Ring of Blood / Gurgthock" },
            { mapID = 121, x = 0.484, y = 0.564, step = 3, label = "Zul'Drak - Amphitheater of Anguish" },
            { mapID = 241, x = 0.5, y = 0.58, step = 4, label = "Crucible of Carnage - Gurgthock" },
        },
        sources = {
            "https://www.wowhead.com/achievement=4958#comments",
