    [4960] = {
        achievementId = 4960,
        name = "Round Three. Fight!",
        category = "Quests",
        sourceType = "Achievement",
        source = "Round Three. Fight!",
        difficulty = "easy",
        difficultyReason = "Finish every fight of the Twilight Highlands arena quest chain.",
        acquisition = "Difficulty: Easy - Finish every fight of the Twilight Highlands arena quest chain.\n\n1. Visit Gurgthock at the Crucible of Carnage in central Twilight Highlands around 50,58. Enable Trivial Quests if overleveled. Accept the first offered Crucible of Carnage challenge.\n\n2. Let each announced challenger enter the arena, defeat it and TURN IN that quest to receive the next challenge. Stay near the ring; accepting another fight before the event resets or leaving the area can interrupt the sequence.\n\n3. Complete the faction-specific opening challenger and the subsequent arena opponents through The Twilight Terror! Turn in the FINAL quest and check Round Three. Fight! A single arena boss kill is not the full chain.",
        stepCount = 3,
        waypoints = { { mapID = 241, x = 0.5, y = 0.58, step = 1, label = "Crucible of Carnage - Gurgthock and arena" } },
        sources = { "https://www.wowhead.com/achievement=4960#comments:id=1104878" },
