            { mapID = 249, x = 0.42, y = 0.12, step = 5, label = "Maker's Ascent - expedition finale" },
        },
        sources = { "https://www.wowhead.com/achievement=4961#comments:id=1320467" },
        reviewedAt = "2026-11-10",
