    [4975] = {
        achievementId = 4975,
        name = "From Hell's Heart I Stab at Thee",
        category = "Exploration",
        sourceType = "Achievement",
        source = "From Hell's Heart I Stab at Thee",
        difficulty = "easy",
        difficultyReason = "A simple high-level kill; low-level attempts need careful underwater kiting.",
        acquisition = "Difficulty: Easy - A simple high-level kill; low-level attempts need careful underwater kiting.\n\n1. Obtain Vashj'ir underwater travel through Sea Legs and The Abyssal Ride. Search the Shimmering Expanse and the drop-off east of Kelp'thar Forest for the enormous named WHALE SHARK. It patrols, so the map shows its search areas rather than a fixed spawn.\n\n2. At a modern high level, use a strong ranged hit and finish the shark immediately; later Retail comments confirm straightforward solo kills. Do not attack an ordinary shark or wait for a loot reward: the correct Whale Shark intentionally drops nothing.\n\n3. If attempting at a level where it survives and can kill you, use a ranged kiter and helpers. Keep the shark roughly 6-20 yards away, near 15 yards, while moving backward through clear water. Melee range is lethal and outranging its leash resets it. Let the kiter build threat before helpers attack.\n\n4. Stay in range for the kill and check the achievement. No title from an old beta build is awarded. A range addon is optional for a low-level kite, not a requirement for a high-level kill.",
        stepCount = 4,
        waypoints = {
            { mapID = 205, x = 0.5, y = 0.5, step = 1, label = "Shimmering Expanse - Whale Shark patrol search" },
            { mapID = 201, x = 0.7, y = 0.5, step = 1, label = "Eastern underwater drop-off - patrol search" },
        },
        sources = {
            "https://www.wowhead.com/achievement=4975#comments:id=1285584",
            "https://www.wowhead.com/achievement=4975#comments:id=1221223",
