    [4980] = {
        achievementId = 4980,
        name = "Stonetalon Mountains Quests",
        category = "Quests",
        sourceType = "Achievement",
        source = "Stonetalon Mountains Quests",
        faction = "Horde",
        difficulty = "medium",
        difficultyReason = "Complete several connected quest chapters, including their prerequisite hand-ins.",
        acquisition = "Difficulty: Medium - Complete several connected quest chapters, including their prerequisite hand-ins.\n\n1. Enable Trivial Quests on the minimap and track this achievement's CURRENT named chapters. Old comments' numeric quest totals predate storyline tracking. Turn in each branch's final quest and take its follow-up before leaving the hub. Start the Stonetalon introduction from Silverwind Refuge in ASHENVALE with We're Not Out of the Woods Yet (25945). Starting directly in Stonetalon can leave only an isolated spider quest available.\n\n2. Follow the Horde military introduction into Krom'gar Fortress, earning its story promotions through the orders at each outpost. Stay for the travel and briefing events that unlock the next rank's quests.\n\n3. Finish Legionnaire, Da Voodoo and A Short-Lived Victory, following the campaign through the western outposts. Continue the final Thal'darah confrontation and Honor... Never Forsake It; the promotion ceremony is not the last chapter.\n\n4. Check all four faction-specific chapters and complete their last hand-ins. The Alliance and Horde routes differ; a breadcrumb from the wrong faction's Ashenvale camp cannot unlock your storyline.\n\n5. Check the remaining named chapters, return to their own hub and finish their hand-ins. A quest marker can be inside a building, on an object or just over the adjoining zone border. Unrelated dungeon quests, repeatable reputation turn-ins and an old total such as 60/60 do not substitute for the current story criteria.",
        stepCount = 5,
        waypoints = {
            { mapID = 63, x = 0.5, y = 0.66, step = 2, label = "Silverwind Refuge - Stonetalon lead" },
            { mapID = 65, x = 0.66, y = 0.65, step = 2, label = "Krom'gar Fortress - military campaign" },
            { mapID = 65, x = 0.58, y = 0.57, step = 3, label = "Windshear Hold / central campaign" },
            { mapID = 65, x = 0.38, y = 0.32, step = 3, label = "Thal'darah area - later campaign" },
        },
        sources = { "https://www.wowhead.com/achievement=4980#comments:id=1184990" },
        reviewedAt = "2026-11-10",
