    [5191] = {
        achievementId = 5191,
        name = "Tragedy in Three Acts",
        category = "Professions",
        sourceType = "Achievement",
        source = "Tragedy in Three Acts",
        difficulty = "medium",
        difficultyReason = "A specific random common-project collection; travel and duplicate solves can prolong it.",
        acquisition = "Difficulty: Medium - A specific random common-project collection; travel and duplicate solves can prolong it.\n\n1. Learn Archaeology from Harrison Jones in Stormwind's library (85.6, 25.8) or Belloc Brightblade in Orgrimmar (49.0, 70.6). Enable Archaeology dig sites on the world map. Dig sites are personal and move as YOU finish them; another player's route does not determine your active sites.\n\n2. Focus Night Elf dig sites in Kalimdor. Clear nearby unwanted sites when they occupy the continent's active slots; waiting beside a completed site does not cause the required project to appear.\n\n3. At an active dig site, stand inside its highlighted boundary and use Survey. Follow the instrument's direction: red means far away, yellow closer, green nearby. Survey again until the fragment object appears, then LOOT it. Continue until the site disappears and a replacement spawns. Clearing unwanted races also frees slots for the race you need.\n\n4. Open Archaeology, select the race whose fragments you collected, and complete its CURRENT research project when you have enough fragments. Insert matching keystones where the project has sockets to reduce its cost. The next project is random: you cannot select an unsolved artifact directly.\n\n5. Finish these Night Elf COMMON artifacts, checking off each distinct name: Delicate Music Box; Hairpin of Silver and Malachite; Cracked Crystal Vial; Cloak Clasp with Antlers; Chest of Tiny Glass Animals; Silver Scroll Case. These are research solves, not dungeon boss drops despite some familiar names. Repeating one artifact does not substitute for a missing named artifact.\n\n6. Optional at Archaeology 600: crate completed common Pandaria artifacts and exchange the Restored Artifacts with Brann above Mogu'shan Palace for Night Elf fragment crates. Solve the projects offered by those fragments. Original Eastern Kingdoms and Kalimdor gray artifacts cannot be converted into these crates.\n\n7. Continue until EVERY named criterion is complete. You cannot force the next research project or guarantee a particular solve within a few hours. Keep reviewing the achievement checklist rather than counting total solves.",
        stepCount = 7,
        waypoints = {
            { mapID = 84, x = 0.856, y = 0.258, step = 1, label = "Harrison Jones - Archaeology trainer" },
            { mapID = 85, x = 0.49, y = 0.706, step = 1, label = "Belloc Brightblade - Archaeology trainer" },
            { mapID = 390, x = 0.835, y = 0.31, step = 6, label = "Brann - optional Night Elf fragment crates" },
        },
        areaMaps = { 12 },
        sources = { "https://www.wowhead.com/achievement=5191#comments:id=1138014" },
