    [5287] = {
        achievementId = 5287,
        name = "Rotten to the Core",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Rotten to the Core",
        difficulty = "medium",
        difficultyReason = "Gather at least 60 followers and kill them yourself while Azil is alive and engaged.",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Gather at least 60 followers and kill them yourself while Azil is alive and engaged.\n\n1. Enter The Stonecore on Heroic. Reach High Priestess Azil without killing the Devout Followers in the Chamber of Fanatics immediately before her or the three groups in front of her platform. Disable damage shields, passive area damage and attacking pets.\n\n2. Body-pull the followers from the preceding room and all three groups beside Azil. Gather more than 60 to give yourself a margin, and bring them together away from her platform. Do not kill any until Azil is actually in combat.\n\n3. Engage Azil with a non-damaging taunt or interrupt from range. As she starts her encounter dialogue and becomes hostile, kill one follower, then immediately kill the gathered followers with your own area damage, within ten seconds. Keep Azil outside that attack so she remains alive.\n\n4. Do this before Gravity Well consumes the pack: deaths caused by her mechanic have inconsistent historical reports, so use your own damage. Confirm the achievement, then kill Azil. If you lose too many followers, reset without killing her; later followers or a trash respawn can provide another attempt.",
        waypoints = {
            {
                mapID = 207,
                x = 0.47600000000000003,
                y = 0.52,
                step = 1,
                label = "The Stonecore - elevated entrance",
                mapName = "Deepholm",
