    [5288] = {
        achievementId = 5288,
        name = "No Static at All",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "No Static at All",
        difficulty = "easy",
        difficultyReason = "Stay airborne for every Static Cling cast that occurs.",
        stepCount = 3,
        acquisition = "Difficulty: Easy - Stay airborne for every Static Cling cast that occurs.\n\n1. Enter The Vortex Pinnacle on Heroic and reach Asaad on the final platform. Track the achievement on YOUR character: another player's failure does not automatically fail yours.\n\n2. Jump into the pull and burst Asaad down before Static Cling if your damage allows it. This is the short numbered profit guide's approach, with its final profit step omitted.\n\n3. For a deliberate attempt, engage without killing him and watch his cast bar. Jump as Static Cling starts so you are in the air when it completes; repeat for every cast, and stand inside the triangle during his storm. Kill him after avoiding the cast. This also provides a fallback if a previous instant kill gave no credit.",
        waypoints = {
            {
                mapID = 249,
                x = 0.767,
                y = 0.8440000000000001,
                step = 1,
                label = "The Vortex Pinnacle - airborne entrance",
