    [5289] = {
        achievementId = 5289,
        name = "Extra Credit Bonus Stage",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Extra Credit Bonus Stage",
        difficulty = "medium",
        difficultyReason = "Collect five airborne orbs in one instance, using jumps, slipstreams and Altairus's tornadoes.",
        stepCount = 5,
        acquisition = "Difficulty: Medium - Collect five airborne orbs in one instance, using jumps, slipstreams and Altairus's tornadoes.\n\n1. Enter The Vortex Pinnacle on Heroic and enable a convenient Interact with Target keybind. Collect FIVE Golden Orbs in the same instance; a party shares the count. Orb positions vary slightly, so inspect the edges and height rather than assuming every old screenshot matches exactly.\n\n2. Check the first bridge's lamps, then the edge near the slipstream behind Grand Vizier Ertan. Defeat Ertan and inspect the bridge containing the two Howling Gales: an orb hangs off either side. Face each orb before jumping, and interact as soon as it is in reach. A movement boost, glide or safe return ability helps.\n\n3. Keep Altairus ALIVE if you still need the two orbs above his arena. Stand beneath an orb and let a moving tornado throw you into reach, then interact while airborne. Remove avoidance gear and sit if tornadoes fail to lift you. Collect both before killing him.\n\n4. If still short, inspect both sides of the upward spiral at Thunder's Rise and the downward spiral toward Asaad. Use the small wind streams for movement speed and jump toward the orb. Falling returns you to the entrance; the unlocked slipstreams there take you back to later platforms.\n\n5. Continue until the fifth orb awards the achievement. You can collect the bridge and spiral orbs after clearing the dungeon, but killing Altairus removes his helpful tornado mechanic. Do not leave and reset the instance between collections.",
