    [5290] = {
        achievementId = 5290,
        name = "Kill It With Fire!",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Kill It With Fire!",
        difficulty = "hard",
        difficultyReason = "Preserve a fire patch, control Barim's health and kill three burning Soul Fragments in the spirit phase.",
        stepCount = 6,
        acquisition = "Difficulty: Hard - Preserve a fire patch, control Barim's health and kill three burning Soul Fragments in the spirit phase.\n\n1. Enter Lost City of the Tol'vir on Heroic and reach High Prophet Barim. Clear nearby trash. Dismiss attacking pets, remove damage procs and prepare a damage-reduction method BEFORE combat so you can lower his health without killing him.\n\n2. Engage without attacking and wait for the red phoenix, Blaze of the Heavens. Let it leave several fire patches on the ground before damaging Barim. Remember their positions: the spirit phase needs that fire.\n\n3. Carefully lower Barim below 50% to trigger Repentance, then stop all damage. An ungeared punch can still be too strong at a high Retail level; Whole-Body Shrinka' reduces your damage. Midnight comments also describe Oil of Immolation and Goblin Dragon Gun, Mark II, but their actual damage must be judged on your character.\n\n4. Leave the purple Harbinger of Darkness ALIVE. Wait for Soul Fragments, the shadow copies of your character. Position yourself so each fragment crosses a retained fire patch on its way toward you. Target it and check for the Burning Soul debuff; its displayed name can flicker back to Soul Fragment.\n\n5. Kill a fragment immediately while Burning Soul is active, using a single-target attack that does not kill the Harbinger. Repeat for THREE qualifying fragments. If one merges or fails to burn, wait for another; do not end the spirit phase early.\n\n6. The achievement appears during the encounter. Only then kill the Harbinger and finish Barim. If the fire setup failed, reset the living boss and rebuild it rather than completing an unsuccessful kill.",
        waypoints = {
            {
                mapID = 249,
                x = 0.605,
                y = 0.6409999999999999,
                step = 1,
                label = "Lost City of the Tol'vir - entrance",
                mapName = "Uldum",
            },
            {
                mapID = 277,
                x = 0.27,
                y = 0.657,
                step = 2,
                label = "Barim - create phoenix fire before 50%",
                mapName = "Lost City of the Tol'vir",
            },
            {
                mapID = 277,
                x = 0.27,
                y = 0.657,
                step = 4,
                label = "Spirit phase - burn and kill three fragments",
                mapName = "Lost City of the Tol'vir",
