    [5293] = {
        achievementId = 5293,
        name = "I Hate That Song",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "I Hate That Song",
        difficulty = "easy",
        difficultyReason = "A high-level direct kill avoids the hymn; a longer fight needs quick lever use and an interrupt.",
        stepCount = 3,
        acquisition = "Difficulty: Easy - A high-level direct kill avoids the hymn; a longer fight needs quick lever use and an interrupt.\n\n1. Enter Halls of Origination on Heroic and reach Temple Guardian Anhuur, the first boss. At a high Retail level, burst him down with your own direct damage before Reverberating Hymn can start. Later comments confirm this can award the achievement without using the levers.\n\n2. If he shields instead, stop attacking the immune boss. Use BOTH beacon levers in the snake pit below to remove his shield, then immediately interrupt Reverberating Hymn. Repeat for the next shield phase; each hymn must be interrupted within the achievement's time limit.\n\n3. For a deliberate lever attempt, bring partners: one holds the snakes away from the levers, two handle the opposite levers, and an available interrupt stops the hymn as soon as the shield drops. Finish Anhuur after both phases. Do not rely on the old health-threshold exploit described in early solo comments.",
        waypoints = {
            { mapID = 249, x = 0.691, y = 0.529, step = 1, label = "Halls of Origination - entrance", mapName = "Uldum" },
            {
                mapID = 297,
