    [5294] = {
        achievementId = 5294,
        name = "Straw That Broke the Camel's Back",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Straw That Broke the Camel's Back",
        difficulty = "easy",
        difficultyReason = "Ride the dungeon's camel for the entire Ptah encounter.",
        stepCount = 3,
        acquisition = "Difficulty: Easy - Ride the dungeon's camel for the entire Ptah encounter.\n\n1. Enter Halls of Origination on Heroic and take the outside sandy route to Earthrager Ptah. Clear the trash before pulling him, then click one of the live camels beside the approach. These are dungeon vehicles; owning a camel mount is unnecessary.\n\n2. Remain on that camel and kill Ptah. At a high Retail level a direct fast kill is enough. If the fight lasts, move out of dark Earth Spike warnings and swirling Quicksand, since either can throw you off the camel.\n\n3. Do not dismount before the boss dies and credit appears. If thrown off while solo, retreat down the approach stairs to reset the living boss, mount another available camel and retry.",
        waypoints = {
            { mapID = 249, x = 0.691, y = 0.529, step = 1, label = "Halls of Origination - entrance", mapName = "Uldum" },
