    [5295] = {
        achievementId = 5295,
        name = "Sun of a....",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Sun of a....",
        difficulty = "easy",
        difficultyReason = "Defeat Rajh before his first solar-energy recharge finishes.",
        stepCount = 3,
        acquisition = "Difficulty: Easy - Defeat Rajh before his first solar-energy recharge finishes.\n\n1. Enter Halls of Origination on Heroic. Use the blue elevator plate and its side control to reach The Four Seats. Rajh is upstairs; searching only the ground-floor halls will not find him.\n\n2. At a high Retail level, select Rajh and kill him directly before he can finish recharging. A quick kill before any recharge is supported by the later comments.\n\n3. If he survives, interrupt his interruptible casts to slow energy use, then finish him during Blessing of the Sun before his energy refills and the recharge completes. Do not wait for a full recharge. His movement to the center is the warning to finish immediately.",
