    [5298] = {
        achievementId = 5298,
        name = "Don't Need to Break Eggs to Make an Omelet",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Don't Need to Break Eggs to Make an Omelet",
        difficulty = "easy",
        difficultyReason = "A direct high-level kill prevents any Faceless Corruptor from reaching an egg.",
        stepCount = 3,
        acquisition = "Difficulty: Easy - A direct high-level kill prevents any Faceless Corruptor from reaching an egg.\n\n1. Enter Grim Batol on Heroic and follow the dungeon through General Umbriss, Forgemaster Throngus and Drahga Shadowburner to Erudax. Finish Drahga's dragon phase so the route onward opens.\n\n2. Kill Erudax directly with your own damage before his Faceless Corruptors can reach the eggs. Later Retail comments confirm that a fast kill meets the achievement; you do not need to wait for a corruptor wave.\n\n3. If the fight lasts, stand in Shadow Gale's safe center, then immediately intercept BOTH corruptors entering from the doorway. Slow and kill them before either begins Twilight Corruption on an egg. Return to Erudax and repeat as necessary until he dies with no egg corrupted.",
        waypoints = {
            { mapID = 241, x = 0.192, y = 0.541, step = 1, label = "Grim Batol - entrance", mapName = "Twilight Highlands" },
            {
