    [5300] = {
        achievementId = 5300,
        name = "The Only Escape",
        category = "Raids",
        sourceType = "Achievement",
        source = "The Only Escape",
        difficulty = "easy",
        difficultyReason = "Release and kill two drakes close together before killing Halfus.",
        acquisition = "Difficulty: Easy - Release and kill two drakes close together before killing Halfus.\n\n1. Enter Bastion of Twilight on Normal or Heroic and stop at Halfus. Start the encounter without killing him; disable passive damage and pets if necessary.\n\n2. Interact with one of the available captive drakes to release it, then release a SECOND drake. Keep both alive until they are together. Do not mistake the boss's own death for the required drake kills.\n\n3. Kill both released drakes within TEN seconds of each other, then kill Halfus. This follows the highly rated numbered profit guide and its confirming replies, with the final filler lines omitted.",
        stepCount = 3,
        waypoints = {
            {
                mapID = 241,
