    [5301] = {
        achievementId = 5301,
        name = "The Boy Who Would be King",
        category = "Professions",
        sourceType = "Achievement",
        source = "The Boy Who Would be King",
        difficulty = "medium",
        difficultyReason = "A specific random common-project collection; travel and duplicate solves can prolong it.",
        acquisition = "Difficulty: Medium - A specific random common-project collection; travel and duplicate solves can prolong it.\n\n1. Learn Archaeology from Harrison Jones in Stormwind's library (85.6, 25.8) or Belloc Brightblade in Orgrimmar (49.0, 70.6). Enable Archaeology dig sites on the world map. Dig sites are personal and move as YOU finish them; another player's route does not determine your active sites.\n\n2. Focus Tol'vir dig sites in original Uldum in Kalimdor. Reach Archaeology 450 and use Zidormi for original Uldum if assaults hide the old zone. Clear other Kalimdor sites to roll Uldum replacements.\n\n3. At an active dig site, stand inside its highlighted boundary and use Survey. Follow the instrument's direction: red means far away, yellow closer, green nearby. Survey again until the fragment object appears, then LOOT it. Continue until the site disappears and a replacement spawns. Clearing unwanted races also frees slots for the race you need.\n\n4. Open Archaeology, select the race whose fragments you collected, and complete its CURRENT research project when you have enough fragments. Insert matching keystones where the project has sockets to reduce its cost. The next project is random: you cannot select an unsolved artifact directly.\n\n5. Finish these Tol'vir COMMON artifacts, checking off each distinct name: Cat Statue with Emerald Eyes; Tiny Oasis Mosaic; Sketch of a Desert Palace; Soapstone Scarab Necklace; Engraved Scimitar Hilt; Canopic Jar. These are research solves, not dungeon boss drops despite some familiar names. Repeating one artifact does not substitute for a missing named artifact.\n\n6. Optional at Archaeology 600: crate completed common Pandaria artifacts and exchange the Restored Artifacts with Brann above Mogu'shan Palace for Tol'vir fragment crates. Solve the projects offered by those fragments. Original Eastern Kingdoms and Kalimdor gray artifacts cannot be converted into these crates.\n\n7. Continue until EVERY named criterion is complete. You cannot force the next research project or guarantee a particular solve within a few hours. Keep reviewing the achievement checklist rather than counting total solves.",
        stepCount = 7,
        waypoints = {
            { mapID = 84, x = 0.856, y = 0.258, step = 1, label = "Harrison Jones - Archaeology trainer" },
            { mapID = 85, x = 0.49, y = 0.706, step = 1, label = "Belloc Brightblade - Archaeology trainer" },
            { mapID = 249, x = 0.56, y = 0.35100000000000003, step = 2, label = "Zidormi - original Uldum for Tol'vir sites" },
            { mapID = 390, x = 0.835, y = 0.31, step = 6, label = "Brann - optional Tol'vir fragment crates" },
        },
        areaMaps = { 249 },
        sources = { "https://www.wowhead.com/achievement=5301#comments:id=1124294" },
        reviewedAt = "2026-11-05",
        wowheadUrl = "https://www.wowhead.com/achievement=5301",
        sourceURL = "https://www.wowhead.com/achievement=5301#comments",
    },
    [5304] = {
        achievementId = 5304,
        name = "Stay Chill",
        category = "Raids",
        sourceType = "Achievement",
        source = "Stay Chill",
        difficulty = "medium",
        difficultyReason = "Maintain seven Wind Chill stacks while completing all three wind-lord kills in their recovery window.",
        acquisition = "Difficulty: Medium - Maintain seven Wind Chill stacks while completing all three wind-lord kills in their recovery window.\n\n1. Enter Throne of the Four Winds on Normal or Heroic. Go to Nezir's northern platform, engage without damaging him and wait for Wind Chill. Every player needing credit must have at least SEVEN stacks when the encounter finishes.\n\n2. At high level, gather seven stacks first, then quickly cross to one outer boss and defeat it. Return through Nezir's platform to refresh Wind Chill, cross to the other outer boss and defeat it, then return to Nezir and kill him before either outer boss recovers. Use movement abilities and keep watching your own stack duration.\n\n3. If an outer lord revives before you finish, bring it down again while retaining the stacks; a recovered boss is not a completed kill. A helper covering an outer platform simplifies the timing, but that helper must also visit Nezir for their own stacks.\n\n4. Avoid Rohash's Wind Blast during the crossings. Do not remove Wind Chill with an immunity, and do not kill Nezir before the stack setup is complete. Confirm credit after all three lords are defeated.",
