    [5315] = {
        achievementId = 5315,
        name = "Digger",
        category = "Professions",
        sourceType = "Achievement",
        source = "Digger",
        difficulty = "easy",
        difficultyReason = "Complete many common projects across cultures; duplicates are unreliable for the unique-project target.",
        acquisition = "Difficulty: Easy - Complete many common projects across cultures; duplicates are unreliable for the unique-project target.\n\n1. Learn Archaeology from Harrison Jones in Stormwind's library (85.6, 25.8) or Belloc Brightblade in Orgrimmar (49.0, 70.6). Enable Archaeology dig sites on the world map. Dig sites are personal and move as YOU finish them; another player's route does not determine your active sites.\n\n2. At an active dig site, stand inside its highlighted boundary and use Survey. Follow the instrument's direction: red means far away, yellow closer, green nearby. Survey again until the fragment object appears, then LOOT it. Continue until the site disappears and a replacement spawns. Clearing unwanted races also frees slots for the race you need.\n\n3. Open Archaeology, select the race whose fragments you collected, and complete its CURRENT research project when you have enough fragments. Insert matching keystones where the project has sockets to reduce its cost. The next project is random: you cannot select an unsolved artifact directly.\n\n4. Finish 10 DIFFERENT COMMON projects and inspect the completed-artifact journal and achievement counter. Rare blue projects advance the rare achievements instead. The written requirement is unique projects; do not plan the route around a temporary report that duplicate commons counted after a bug fix.\n\n5. When one culture repeatedly offers artifacts already in your journal, move to cultures with missing commons. Eastern Kingdoms supplies Dwarf and Troll; Kalimdor supplies Night Elf and Fossil; Outland supplies Orc and Draenei; Northrend supplies Nerubian and Vrykul. Tol'vir and later-expansion cultures add more choices.\n\n6. Continue until the live counter reaches 10. The older progress-reset issue was reported fixed around Midnight prepatch; current collection comments confirm renewed progress. If your own journal fails to retain a solve, check it before committing to another long session.",
        stepCount = 6,
        waypoints = {
            { mapID = 84, x = 0.856, y = 0.258, step = 1, label = "Harrison Jones - Archaeology trainer" },
            { mapID = 85, x = 0.49, y = 0.706, step = 1, label = "Belloc Brightblade - Archaeology trainer" },
        },
        areaMaps = { 13, 12, 101, 113 },
        sources = {
            "https://www.wowhead.com/achievement=5315#comments:id=1299649",
            "https://www.wowhead.com/achievement=5470#comments:id=1222281",
            "https://www.wowhead.com/achievement=5470#comments:id=6346617",
        },
        reviewedAt = "2026-11-05",
        wowheadUrl = "https://www.wowhead.com/achievement=5315",
        sourceURL = "https://www.wowhead.com/achievement=5315#comments",
    },
    [5317] = {
        achievementId = 5317,
        name = "Help the Bombardier! I'm the Bombardier!",
        category = "Quests",
        sourceType = "Achievement",
        source = "Help the Bombardier! I'm the Bombardier!",
        difficulty = "medium",
        difficultyReason = "Time artillery impacts on groups of Schnottz infantry.",
        acquisition = "Difficulty: Medium - Time artillery impacts on groups of Schnottz infantry.\n\n1. Follow Harrison Jones's original-Uldum expedition into Schnottz's Landing until Fire From the Sky is available. Accept the quest and use its artillery vehicle. The introductory version can also award the achievement; you do not have to wait for a later daily version.\n\n2. Track the achievement and watch infantry groups on the temple stairs. Aim for the densest clustered group rather than isolated soldiers, accounting for their movement while the shell travels.\n\n3. The comments describe a short kill window: fire first at a FAR group, then as soon as the gun's cooldown ends fire at a NEAR group so both shells land together. The farther shell takes longer to travel, allowing their impacts to overlap and reach ten kills.\n\n4. Check credit after the impacts. If short of ten, let new groups form and repeat while the quest vehicle remains available. Do not finish and turn in the daily before securing the achievement if you still need another attempt.",
        stepCount = 4,
        waypoints = { { mapID = 249, x = 0.22, y = 0.64, step = 1, label = "Schnottz's Landing - Fire From the Sky campaign branch" } },
        sources = {
            "https://www.wowhead.com/achievement=5317#comments:id=1217420",
            "https://www.wowhead.com/achievement=5317#comments:id=1248733",
            "https://www.wowhead.com/achievement=5317#comments:id=5258822",
        },
        reviewedAt = "2026-11-10",
        wowheadUrl = "https://www.wowhead.com/achievement=5317",
        sourceURL = "https://www.wowhead.com/achievement=5317#comments",
    },
    [5318] = {
        achievementId = 5318,
        name = "20,000 Leagues Under the Sea",
        category = "Quests",
        sourceType = "Achievement",
        source = "20,000 Leagues Under the Sea",
        difficulty = "medium",
        difficultyReason = "Finish the underwater campaign through its scripted Rift defense.",
        acquisition = "Difficulty: Medium - Finish the underwater campaign through its scripted Rift defense.\n\n1. Use a Alliance character and follow Vashj'ir's introduction through Kelp'thar Forest and all three Shimmering Expanse Battlemaiden visions. Continue Full Circle into the Abyssal Depths. Starting the Throne of the Tides dungeon alone does not unlock this quest achievement.\n\n2. Complete the Abyssal Depths' Bio-Fuel / Fuel-ology branch and the Earthen Ring work around the ancients. Follow Scalding Shrooms, Into the Totem, ... It Will Come, Unplug L'ghorek and Communing with the Ancient, completing the offered prerequisites instead of jumping straight to the Breach.\n\n3. Finish Runestones of Binding, Ascend No More!, Twilight Extermination and All that Rises, then return to your faction's cave/ship hub for Defending the Rift. Speak to the quest NPC and take the SCRIPTED transport; ordinary swimming to the whirlpool is not the transport event.\n\n4. Stay through the naga/Neptulon defense and finish Defending the Rift's final hand-in. After the third event/cutscene, find the turn-in NPC on the cliff and check the matching faction achievement. If the event stalls, leave the vehicle and retry the quest's transport rather than clearing an unrelated dungeon.",
        stepCount = 4,
        waypoints = {},
        areaMaps = { 201, 205, 204 },
        faction = "Alliance",
        sources = { "https://www.wowhead.com/achievement=5318/20-000-leagues-under-the-sea#comments" },
        reviewedAt = "2026-11-10",
        wowheadUrl = "https://www.wowhead.com/achievement=5318",
        sourceURL = "https://www.wowhead.com/achievement=5318#comments",
    },
    [5319] = {
        achievementId = 5319,
        name = "20,000 Leagues Under the Sea",
        category = "Quests",
        sourceType = "Achievement",
        source = "20,000 Leagues Under the Sea",
        difficulty = "medium",
        difficultyReason = "Finish the underwater campaign through its scripted Rift defense.",
        acquisition = "Difficulty: Medium - Finish the underwater campaign through its scripted Rift defense.\n\n1. Use a Horde character and follow Vashj'ir's introduction through Kelp'thar Forest and all three Shimmering Expanse Battlemaiden visions. Continue Full Circle into the Abyssal Depths. Starting the Throne of the Tides dungeon alone does not unlock this quest achievement.\n\n2. Continue the Abyssal Depths' Earthen Ring and ancient-creature quest branches. At Tenebrous Cavern, check Orako's offered quests: his Promontory Point work must be finished before he offers the final Rift defense. Follow the remaining active quest breadcrumbs rather than copying an Alliance-only submarine chain.\n\n3. Accept Defending the Rift (26194) from Orako in Tenebrous Cavern once his preceding quests are complete. Take the quest's scripted transport and stay through its THREE automatic event/cutscene stages; simply swimming to the whirlpool or entering Throne of the Tides does not complete the quest.\n\n4. Stay through the naga/Neptulon defense and finish Defending the Rift's final hand-in. After the third event/cutscene, find the turn-in NPC on the cliff and check the matching faction achievement. If the event stalls, leave the vehicle and retry the quest's transport rather than clearing an unrelated dungeon.",
