    [5320] = {
        achievementId = 5320,
        name = "King of the Mountain",
        category = "Quests",
        sourceType = "Achievement",
        source = "King of the Mountain",
        difficulty = "medium",
        difficultyReason = "The later Twilight's Hammer finale, beyond the zone's initial story achievement.",
        acquisition = "Difficulty: Medium - The later Twilight's Hammer finale, beyond the zone's initial story achievement.\n\n1. Finish your faction's Twilight Highlands story toward the Twilight Gate and southern assault. Fading into Twilight can finish BEFORE this final chain, so continue with the southern campaign even if that zone achievement already appeared.\n\n2. Follow Initiate Goldmine at the Elementium Depths and take his ride into the mine. Complete the offered side-by-side objectives and click the rune inside to accept Rune Ruination. This easy-to-miss object is required to continue the finale.\n\n3. Finish the rune branch and A Fiery Reunion, kill Magmatooth, and use the exit portal. Continue the faction contact's call and The Hammer of Twilight to unlock Skullcrusher the Mountain.\n\n4. Complete Skullcrusher's scripted confrontation using the quest's NPC/vehicle prompts, then turn it in and check King of the Mountain. Killing an unrelated Twilight giant or clearing Bastion of Twilight does not replace this quest finale.",
        stepCount = 4,
        waypoints = { { mapID = 241, x = 0.38, y = 0.89, step = 2, label = "Elementium Depths - Initiate Goldmine and rune quest" } },
