    [5322] = {
        achievementId = 5322,
        name = "In Service of the Alliance",
        category = "PvP",
        sourceType = "Achievement",
        source = "In Service of the Alliance",
        faction = "Alliance",
        difficulty = "medium",
        difficultyReason = "Win 10 eligible organized rated battlegrounds; long milestones require sustained team participation.",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Win 10 eligible organized rated battlegrounds; long milestones require sustained team participation.\n\n1. Choose an Alliance character, track the 10-victory version of In Service of the Alliance and note its current counter. Keep the character whose unfinished counter you are progressing; do not assume separate incomplete character counters combine.\n\n2. Join or form an organized Rated Battleground team and use the traditional rated battleground queue. The old victory achievements still have recent reports of NO credit from Rated Battleground Blitz, including June 2026 confirmations. Blitz eligibility for rating titles does not establish eligibility for these win counters.\n\n3. Complete and WIN matches, playing the map's objectives with the team. A loss, an ordinary random-battleground win or simply reaching a rating threshold does not add the required rated victory. After the first win, inspect the tracked counter to confirm you are in the correct mode before committing to the long milestone.\n\n4. Continue until 10 eligible victories are credited. There is no requirement to recreate an old Cataclysm season. For the 75-, 150- and 300-win rewards, inspect the actual achievement reward and mailbox afterward: later comments describe Vicious Saddles and occasional delivery bugs, so do not expect the old duplicate mount automatically in your bags.",
        sources = { "https://www.wowhead.com/achievement=5328#comments:id=6366328" },
        waypoints = {},
        wowheadUrl = "https://www.wowhead.com/achievement=5322",
        sourceURL = "https://www.wowhead.com/achievement=5322#comments",
        tips = "This is a queue-based competitive objective with no fixed world destination. An unrelated city or vendor pin would not identify its acquisition location.",
    },
