    [5330] = {
        achievementId = 5330,
        name = "Private",
        category = "PvP",
        sourceType = "Achievement",
        source = "Private",
        faction = "Alliance",
        difficulty = "medium",
        difficultyReason = "Requires reaching 1100 personal rating in a competitive battleground bracket.",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Requires reaching 1100 personal rating in a competitive battleground bracket.\n\n1. Use an Alliance character and track Private. Prepare current PvP gear, a working PvP talent setup, interrupt and crowd-control keybinds, and the current rated-queue eligibility shown by the PvP panel. This is the Retail rated title, not the retired original Honor-rank feat.\n\n2. Choose either Rated Battlegrounds with an organized team or Rated Battleground Blitz through its rated queue. The CURRENT rating achievement accepts either bracket. Random battlegrounds, unranked brawls, skirmishes and arena rating do not provide this battleground title.\n\n3. Win objective-focused games until the selected bracket's PERSONAL rating reaches 1100. Call incoming attacks early, coordinate crowd control with your team and prioritize flags or bases over unrelated damage. Matchmaking rating, Honor level and Conquest currency totals are different values and do not replace the displayed personal rating.\n\n4. Check achievement credit as soon as 1100 rating is reached, then select Private in your character title list if desired. Do not wait for a Cataclysm-season ending: this rating title remains obtainable, while the removed Vicious/Ruthless/Cataclysmic season awards were separate achievements.",
        sources = { "https://www.wowhead.com/achievement=5330#comments:id=2870876" },
