    [5363] = {
        achievementId = 5363,
        name = "250000 Honorable Kills",
        category = "PvP",
        sourceType = "Achievement",
        source = "250000 Honorable Kills",
        difficulty = "hard",
        difficultyReason = "A very long cumulative honorable-kill grind.",
        acquisition = "Difficulty: Hard - A very long cumulative honorable-kill grind.\n\n1. Track the honorable-kill total and queue for eligible PvP battlegrounds. Battle for Gilneas and Twin Peaks can also progress their own achievements, while large battleground fights offer many shared honorable-kill opportunities.\n\n2. Stay with your team in active fights against eligible opposing players. Contribute damage, healing or support while close enough for honorable-kill credit. You need HONORABLE KILLS, not 250,000 personal killing blows; NPC kills, raw honor currency and player kills without HK credit are different counters.\n\n3. When Training Grounds is offered, recent Retail comments confirm it can advance this achievement. Inspect your counter before and after the first match so you know that the current queue mode is crediting it before investing in repeated games.\n\n4. Repeat eligible matches until the total reaches 250,000. There is no one-match requirement. Check the live account/character progress shown by the achievement rather than assuming all alt statistics sum exactly the same way.",
        stepCount = 4,
        waypoints = {},
        areaMaps = { 206, 275 },
        sources = {
