    [5374] = {
        achievementId = 5374,
        name = "45 Exalted Reputations",
        category = "Reputation",
        sourceType = "Achievement",
        source = "45 Exalted Reputations",
        difficulty = "hard",
        difficultyReason = "Many separate reputation grinds, including time-gated factions.",
        acquisition = "Difficulty: Hard - Many separate reputation grinds, including time-gated factions.\n\n1. Track 45 Exalted Reputations and check its live distinct-faction total. Make a list of factions already close to Exalted; another copy of the same faction on an alt is not a new unique reputation. Use the current tracker when combining Warband progress.\n\n2. Fill quick dungeon reputations: wear city tabards for eligible city reputation, use the four original Northrend championing tabards, and use the six Cataclysm championing factions. At Friendly buy the matching tabard, equip it, and verify the kill log awards the intended faction before repeating a dungeon.\n\n3. Add original Outland dungeon factions through their own dungeons: Cenarion Expedition in Coilfang, Lower City in Auchindoun, Sha'tar in Tempest Keep dungeons, and Keepers of Time in the Caverns of Time. A Cataclysm tabard is not a substitute for these factions' default dungeon reputation.\n\n4. Use raid clears for Hydraxian Waterlords, Brood of Nozdormu, Violet Eye, Ashtongue, Ashen Verdict and Avengers of Hyjal. Observe each faction's trash cap and finish the remaining bar with eligible bosses or its required turn-ins. Combine these with your weekly mount and legendary routes.\n\n5. Fill remaining slots with currently available daily factions, such as Ramkahen, Therazane, Tol Barad, Kalu'ak and later-expansion factions. Keep their hand-in schedule and actual reputation bars visible; retired factions and an old mutually exclusive counterpart need not be part of the route.\n\n6. Continue until the live counter reaches 45. Rank/renown displays from later systems do not automatically mean that an Exalted criterion counted; verify each planned addition rather than assuming every reputation UI bar contributes.",
        stepCount = 6,
        waypoints = {
            { mapID = 249, x = 0.54, y = 0.332, step = 2, label = "Ramkahen - championing tabard" },
            { mapID = 207, x = 0.568, y = 0.132, step = 2, label = "Therazane - tabard after campaign" },
            { mapID = 118, x = 0.535, y = 0.855, step = 4, label = "ICC - Ashen Verdict" },
            { mapID = 198, x = 0.47200000000000003, y = 0.7809999999999999, step = 4, label = "Firelands - Avengers of Hyjal" },
        },
        sources = { "https://www.wowhead.com/achievement=5374#comments", "https://www.wowhead.com/achievement=5723#comments" },
        reviewedAt = "2026-11-05",
        wowheadUrl = "https://www.wowhead.com/achievement=5374",
        sourceURL = "https://www.wowhead.com/achievement=5374#comments",
    },
    [5375] = {
        achievementId = 5375,
        name = "Baradin's Wardens",
        category = "Reputation",
        sourceType = "Achievement",
        source = "Baradin's Wardens",
        difficulty = "medium",
        difficultyReason = "A repeated daily-quest reputation with extra opportunities while your faction controls Tol Barad.",
        acquisition = "Difficulty: Medium - A repeated daily-quest reputation with extra opportunities while your faction controls Tol Barad.\n\n1. Use a Alliance character. Take the capital's Tol Barad portal and visit your faction camp on TOL BARAD PENINSULA. Accept its daily quests; they are available even when the enemy controls the southern PvP island.\n\n2. Complete the Peninsula objectives and return for the hand-ins. The offered variants rotate, so follow today's quest log rather than a fixed old list. These hand-ins are the steady reputation route.\n\n3. When your faction controls TOL BARAD, cross to the southern island and collect the bonus dailies near Baradin Hold. Complete the fixed quests and the currently open prison wing's three quests, then turn them in before the relevant access changes.\n\n4. If you participate in Tol Barad battles, winning also awards reputation and may change the prison quest rotation. Already completed daily variants do not become infinitely repeatable after another win. Repeat available quests after daily resets until EXALTED.\n\n5. Check the faction reputation achievement. The Tol Barad tabard is a commendation-purchased teleport item, not a dungeon championing tabard; repeatedly killing dungeon trash while wearing it is not this reputation route.",
        stepCount = 5,
        waypoints = {
            { mapID = 245, x = 0.725, y = 0.626, step = 1, label = "Baradin's Wardens - Peninsula daily camp" },
            { mapID = 244, x = 0.514, y = 0.496, step = 3, label = "Tol Barad - controlling faction's outdoor daily hub" },
        },
        sources = { "https://www.wowhead.com/achievement=5375#comments:id=1375910" },
        reviewedAt = "2026-11-05",
        wowheadUrl = "https://www.wowhead.com/achievement=5375",
