        category = "PvP",
        sourceType = "Achievement",
        source = "Tower Plower",
        difficulty = "hard",
        difficultyReason = "Attack-side siege use needs a Veteran buff and the tower's finishing hit.",
        acquisition = "Difficulty: Hard - Attack-side siege use needs a Veteran buff and the tower's finishing hit.\n\n1. Take the capital's Tol Barad portal to the PENINSULA, then cross to the southern battle island. Check the actual zone battle state and join the outdoor Tol Barad battle when it opens. The island and the daily-quest Peninsula are different maps.\n\n2. Attempt this when your faction is ATTACKING. Earn the Veteran buff from an eligible enemy-player honorable kill during this battle so you can drive a siege engine. A normal NPC kill does not provide that player-PvP requirement.\n\n3. Enter a siege engine, drive within range of an intact enemy tower and use Deploy Siege Engine. You leave the vehicle and it attacks automatically. Deploy additional engines if needed while keeping your original engines alive.\n\n4. Let YOUR deployed siege deal the tower's finishing hit. You do not have to stand next to the tower at that instant, but another player's engine dealing the final hit can miss your credit. Check the achievement after destruction; return in a later attacking battle if the opportunity is lost.",
        stepCount = 4,
        waypoints = { { mapID = 244, x = 0.5, y = 0.49, step = 1, label = "Tol Barad - attacking battle / siege towers" } },
