    [5442] = {
        achievementId = 5442,
        name = "Full Caravan",
        category = "Quests",
        sourceType = "Achievement",
        source = "Full Caravan",
        difficulty = "medium",
        difficultyReason = "Recruit eight companions through Fiona's connected quest branches.",
        acquisition = "Difficulty: Medium - Recruit eight companions through Fiona's connected quest branches.\n\n1. Begin with Fiona at the western entrance to Eastern Plaguelands (9.0,66.4). Rescue Gidwin Goldbraids near Terrorweb Tunnel and help Tarenar Sunstrike along the road. Complete each paladin's errands and return to Fiona; both must be ready before the caravan can leave.\n\n2. Ride the caravan to Crown Guard Tower. Finish Traveling Companions and Argus Highbeacon's tower quests; speak to Argus on the roof and continue the caravan dialogue. Complete Pamela Redpath's doll/Darrowshire branch through The Battle of Darrowshire for her recruitment.\n\n3. Continue to Light's Shield Tower. Complete Vex'tul's local branch and Fiona's Boys Will Be Boys / A Boyhood Dream sequence. Follow the paladins to Light's Hope Chapel even if the wagon temporarily stays behind.\n\n4. At Light's Hope, find Rimblat Earthshatter and Beezil Linkspanner around 73.8,52.1. Do Rimblat's Gathering Some Grub(s) and An Opportune Alliance; continue the caravan to the next stop so his recruitment registers. Beezil has a TALK option, not necessarily a quest marker: explicitly invite him to join.\n\n5. Check Fiona, Gidwin, Tarenar, Argus, Pamela, Vex'tul, Rimblat and Beezil individually. Continue the caravan's Eastwall/Northpass rescue story if needed, looting The Baroness' Missive during the Gidwin search. Travel to the wagon's current stop on a partially completed character instead of expecting a second Fiona at the original start.\n\n6. If Beezil cannot be recruited, check that you are at least Neutral with Gadgetzan rather than hostile from Bloodsail farming. If dialogue succeeded but the criterion did not refresh, log OUT and back IN and speak again; /reload alone did not fix this in the replies.",
        stepCount = 6,
        waypoints = {
            { mapID = 23, x = 0.09, y = 0.664, step = 1, label = "Fiona - caravan start" },
            { mapID = 23, x = 0.35200000000000004, y = 0.688, step = 2, label = "Crown Guard Tower - Argus and caravan" },
            { mapID = 23, x = 0.35, y = 0.8440000000000001, step = 2, label = "Darrowshire - Pamela's branch" },
            { mapID = 23, x = 0.5379999999999999, y = 0.539, step = 3, label = "Light's Shield Tower - Vex'tul / Fiona" },
            { mapID = 23, x = 0.738, y = 0.521, step = 4, label = "Light's Hope - Rimblat and Beezil" },
            { mapID = 23, x = 0.5054, y = 0.20129999999999998, step = 5, label = "Northpass - later caravan rescue" },
        },
        sources = {
            "https://www.wowhead.com/achievement=5442#comments:id=1200708",
