    [5443] = {
        achievementId = 5443,
        name = "E'ko Madness",
        category = "Quests",
        sourceType = "Achievement",
        source = "E'ko Madness",
        difficulty = "medium",
        difficultyReason = "Seven random Juju buffs from different Winterspring creatures.",
        acquisition = "Difficulty: Medium - Seven random Juju buffs from different Winterspring creatures.\n\n1. Track E'ko Madness and visit Winterspring. You need the JUJU BUFF from kills, not a looted E'ko item. No old Cache of Mau'ari or prerequisite quest is required. Dismiss attacking pets so your character receives the killing blow and buff.\n\n2. Around Everlook's eastern side, kill Winterfall furbolgs near 68,50 for Juju Frenzy, then Ice Thistle yetis near 67,54 for Juju Chill. Repeat each creature type until its own achievement criterion checks.\n\n3. Head south to Frostwhisper Gorge around 65,69 and kill Frostmaul giants/tumblers for Juju Brawn. Its proc may take many kills; later Retail comments confirm tumblers can count. Continue until the BUFF and criterion actually appear.\n\n4. Sweep north: Shardtooth bears near 59,40 give Juju Mending; wildkin around 64,28 give Juju Instinct; Chillwind chimaeras around 56,28 give Juju Freeze; frostsabers around 47,19 give Juju Fury. Each is a random buff proc, not a guaranteed first-kill objective.\n\n5. Check all seven entries. The buffs may coexist and do not have to be active simultaneously. If a buff persistently fails, remove conflicting temporary buffs and retry, but gear removal is not a general requirement: 2025/2026 comments confirm ordinary geared kills.",
        stepCount = 5,
        waypoints = {
            { mapID = 83, x = 0.68, y = 0.5, step = 2, label = "Winterfall furbolgs - Frenzy" },
            { mapID = 83, x = 0.67, y = 0.54, step = 2, label = "Ice Thistle yetis - Chill" },
            { mapID = 83, x = 0.65, y = 0.69, step = 3, label = "Frostmaul giants / tumblers - Brawn" },
            { mapID = 83, x = 0.59, y = 0.4, step = 4, label = "Shardtooth bears - Mending" },
