    [5444] = {
        achievementId = 5444,
        name = "Ready, Set, Goat!",
        category = "Quests",
        sourceType = "Achievement",
        source = "Ready, Set, Goat!",
        difficulty = "easy",
        difficultyReason = "Twelve nearby goats in a one-minute item-use circuit.",
        acquisition = "Difficulty: Easy - Twelve nearby goats in a one-minute item-use circuit.\n\n1. At Fuselight in Badlands, accept It's Goat Time, Baby from Garyanne Fleezlebop and keep the supplied Billy Goat Blaster. If you already finished the quest, buy Billy Goat Blaster DX from nearby Gina Gotgoods around 64.25,37.46; replies report the purchase unlock requires finishing the quest first.\n\n2. Put the blaster on an action bar and track the achievement. Optionally bind a two-line macro: /targetexact Billy Goat, then /use Billy Goat Blaster. For the bought version, the second line must instead say /use Billy Goat Blaster DX.\n\n3. Mount and move through the goats around Fuselight. Get CLOSE to each target, use the blaster, and immediately move to another goat. Targeting from too far away wastes the timer even when the macro finds a goat.\n\n4. Blast TWELVE within one minute, then check credit before turning in the quest. If you miss the window, wait for the counter to reset and start another uninterrupted circuit. Later reports of a forgiving timer are not a reason to deliberately wait between shots.",
        stepCount = 4,
        waypoints = {
            { mapID = 15, x = 0.6425, y = 0.3746, step = 1, label = "Fuselight - Garyanne / Gina and blasters" },
            { mapID = 15, x = 0.6425, y = 0.3746, step = 3, label = "Fuselight goat circuit - stay close to targets" },
        },
        sources = {
            "https://www.wowhead.com/achievement=5444#comments:id=1256575",
            "https://www.wowhead.com/achievement=5444#comments:id=1488360",
            "https://www.wowhead.com/achievement=5444#comments:id=5912708",
