    [5445] = {
        achievementId = 5445,
        name = "Fungalophobia",
        category = "Quests",
        sourceType = "Achievement",
        source = "Fungalophobia",
        difficulty = "medium",
        difficultyReason = "Therazane progression followed by a rotating daily quest.",
        acquisition = "Difficulty: Medium - Therazane progression followed by a rotating daily quest.\n\n1. Finish Deepholm's World Pillar/Therazane campaign until the Throne offers daily quests. Reputation alone on a fresh character does not unlock the quest hubs. Use the Temple of Earth's unlocked Throne portal or fly north and check today's blue quest markers.\n\n2. At REVERED, check Ruberick at Therazane's Throne for the rotating daily Glop, Son of Glop (28390). It is not offered every day. The original one-time version of Glop's story is not the daily required here.\n\n3. Enter Glop's cave around 68.63,28.61, speak to Earthmender Norsala and start YOUR event. Follow Glop between his stopping places. When he becomes attackable, kill him; at a high level you can finish him at the first attackable stop.\n\n4. Avoid damage from every Boomshroom. Keep moving away from each small mushroom before its delayed explosion, or destroy it before detonation. A quick kill can avoid all casts. If you were hit, abandon and retake the daily BEFORE its hand-in to retry.\n\n5. TURN IN the daily to receive achievement credit. The achievement normally does not appear at Glop's death. Pet damage from mushrooms is not the same as your character taking forbidden damage.",
        stepCount = 5,
        waypoints = {
            { mapID = 207, x = 0.5660000000000001, y = 0.14, step = 2, label = "Ruberick - rotating Glop daily" },
            { mapID = 207, x = 0.6862999999999999, y = 0.2861, step = 3, label = "Glop cave - speak to Norsala inside" },
        },
        sources = {
