    [5447] = {
        achievementId = 5447,
        name = "My Very Own Broodmother",
        category = "Quests",
        sourceType = "Achievement",
        source = "My Very Own Broodmother",
        difficulty = "medium",
        difficultyReason = "The ninety-second timer includes the quest turn-in.",
        acquisition = "Difficulty: Medium - The ninety-second timer includes the quest turn-in.\n\n1. Finish Deepholm's World Pillar/Therazane campaign until the Throne offers daily quests. Reputation alone on a fresh character does not unlock the quest hubs. Use the Temple of Earth's unlocked Throne portal or fly north and check today's blue quest markers.\n\n2. Accept the rotating Restless Brood daily and travel to the Resonating Crystal in the Pale Roost around 40,19. Put its supplied mallet on an action bar and identify the nearby quest turn-in BEFORE starting the timed attempt.\n\n3. Strike the crystal to start the timer, let the stone giant throw you onto the floating rocks, and click the next rocks to climb. You can skip an intermediate rock when the next is in range. Move off a rock before it falls.\n\n4. Bring Aeosera into range and damage her until she submits. At a modern high level this can be very quick. Leave the rock vehicle, return to the nearby giant and TURN IN Restless Brood within NINETY SECONDS of the crystal strike.\n\n5. Check the achievement after hand-in. The old comments' repeated-crystal timer-reset trick has conflicting replies; a normal fast climb, submission and nearby turn-in avoids depending on it. If the attempt fails, retry on a future offered daily.",
        stepCount = 5,
        waypoints = {
            { mapID = 207, x = 0.573, y = 0.125, step = 2, label = "Therazane's Throne - Restless Brood" },
            { mapID = 207, x = 0.4, y = 0.19, step = 2, label = "Pale Roost - crystal and nearby turn-in" },
        },
        sources = {
