    [5448] = {
        achievementId = 5448,
        name = "Glutton for Fiery Punishment",
        category = "Quests",
        sourceType = "Achievement",
        source = "Glutton for Fiery Punishment",
        difficulty = "medium",
        difficultyReason = "Avoid the trial hazards while building an uninterrupted counter.",
        acquisition = "Difficulty: Medium - Avoid the trial hazards while building an uninterrupted counter.\n\n1. Go to Archmage Xylem's Arcane Pinnacle in northern Azshara around 55.98,12.16. Both factions can attempt these achievements, including after finishing the apprentice quests. Use the corresponding crystal AND its opened portal, or travel directly to the trial area shown on the guide map.\n\n2. Enter the Trial of Fire around 33,23.5. Track the achievement before starting so a failed attempt is visible.\n\n3. Watch where the small purple projectiles land: those circles ignite NEXT. Move into a circle that received no projectile and remain safe as the fire cycle resolves. Repeat for TEN Fire Dancing stacks without taking damage. The /dance emote is unnecessary.\n\n4. Do not blindly follow the apprentice NPC, who can cross fire. With flying available, hover above the hazards while locating the next safe circle, then land for its credit. Track the achievement counter; being visually near a circle does not mean its next burst is safe.\n\n5. When the required uninterrupted count is credited, check the achievement before leaving the trial. Damage resets the attempt; ordinary completion of the apprentice quest is not proof that its special avoidance achievement succeeded.",
        stepCount = 5,
        waypoints = {
            { mapID = 76, x = 0.5598, y = 0.1216, step = 1, label = "Arcane Pinnacle - trial crystals and portals" },
            { mapID = 76, x = 0.33, y = 0.235, step = 2, label = "Trial of Fire" },
        },
        sources = {
            "https://www.wowhead.com/achievement=5448#comments:id=1181960",
            "https://www.wowhead.com/achievement=5448#comments:id=1222791",
            "https://www.wowhead.com/achievement=5448#comments:id=2554236",
            "https://www.wowhead.com/achievement=5448#comments:id=3121686",
        },
        reviewedAt = "2026-11-10",
        wowheadUrl = "https://www.wowhead.com/achievement=5448",
        sourceURL = "https://www.wowhead.com/achievement=5448#comments",
    },
    [5449] = {
        acquisition = "Difficulty: Medium - A long Deepholm unlock and ten completions of a rotating daily; the escort itself is simple.\n\n1. Enter Deepholm through your faction capital's Cataclysm portal. Finish the Temple of Earth and Earthen/Therazane story until Therazane's Throne offers daily quests. Being high level or Exalted does not replace the quest unlock on a new character.\n\n2. Check Pyrite at Therazane's Throne, around 57.3,12.5, for Lost In The Deeps. If it is absent, return after a daily reset. Accepting other dailies does not guarantee this specific one will appear.\n\n3. Enter the Crumbling Depths near 59.0,25.0. Follow behind the Colossal Gyreworm around the circular tunnel, avoiding its body, then take the exit into the large crystal chamber. Follow the right-hand passage and its left turn to Pebble's ledge near 63.2,20.8; talk to him.\n\n4. Escort him back along the tunnels on foot. Pause at corners and the low rock ramp so he follows; avoid jumping away or running far ahead. At the cave mouth wait for the rescue objective to complete before flying off. If lost, return for Pebble; leave and re-enter the cave if he does not reset.\n\n5. Turn in the daily to Pyrite. Repeat on available days until Rock Lover reaches 10/10, then check your Pet Journal and reward mail for Pebble. Learn any awarded pet item.\n\n6. Eligible Warband characters can contribute separate daily hand-ins to the shared counter in recent Retail reports. Each character still needs its OWN Deepholm daily unlock; reputation alone is insufficient. Verify the counter after the first alt hand-in before repeating the trip on more characters.",
        stepCount = 6,
        waypoints = {
            {
                mapID = 207,
                x = 0.573,
                y = 0.125,
                step = 2,
                label = "Pyrite / Therazane's Throne - rotating daily",
                mapName = "Deepholm",
            },
            { mapID = 207, x = 0.59, y = 0.25, step = 3, label = "Crumbling Depths - cave entrance", mapName = "Deepholm" },
            {
                mapID = 207,
                x = 0.632,
                y = 0.20800000000000002,
                step = 3,
                label = "Pebble - underground ledge, follow tunnels",
                mapName = "Deepholm",
            },
            { mapID = 207, x = 0.59, y = 0.25, step = 4, label = "Cave exit - wait for rescue credit", mapName = "Deepholm" },
            { mapID = 207, x = 0.573, y = 0.125, step = 5, label = "Pyrite - turn in Lost In The Deeps", mapName = "Deepholm" },
        },
        difficulty = "medium",
        difficultyReason = "A long Deepholm unlock and ten completions of a rotating daily; the escort itself is simple.",
        tips = "The daily is not guaranteed every day and the ten completions need not be consecutive. Use one character for the counter. Underground Economy held in your log can interfere with this daily's shared slot; finish or abandon it before checking.",
        category = "Quests",
        sourceType = "Achievement",
