    [5450] = {
        achievementId = 5450,
        name = "Fungal Frenzy",
        category = "Quests",
        sourceType = "Achievement",
        source = "Fungal Frenzy",
        difficulty = "medium",
        difficultyReason = "Collect three short buffs, then trigger the instantaneous fourth mushroom effect.",
        acquisition = "Difficulty: Medium - Collect three short buffs, then trigger the instantaneous fourth mushroom effect.\n\n1. Finish Deepholm's World Pillar/Therazane campaign until the Throne offers daily quests. Reputation alone on a fresh character does not unlock the quest hubs. Use the Temple of Earth's unlocked Throne portal or fly north and check today's blue quest markers.\n\n2. Accept Fungal Fury from Gorsik at Therazane's Throne. The clickable Crimson Mushrooms only appear while this daily is active. Fly to the Crimson Expanse and scout examples of all four mushroom types before collecting any.\n\n3. Collect Shrinkshroom and Shuffletruffle, checking the actual debuff names. Suggested search areas are near 68.7,41.5 for Shrinkshroom and 74,39 for Shuffletruffle, but individual spawns vary. The beige/pink and blue/spotted mushrooms can share spawn areas.\n\n4. While those buffs remain active, collect Poolstool, the large red mushroom near the water around 75,34. Stay OUT of the water and inside the quest area: leaving it or entering water can remove the buffs.\n\n5. LAST, click a purple spotted Trapcap near the large crystal formations, for example around 72,40. Its explosion has no lasting buff, so it must happen while all three other effects are present. Put your back toward a wall to shorten the knockback and check credit.\n\n6. If the daily's ten mushroom clicks are used up without credit, abandon and reaccept it before hand-in to make another attempt. Mushroom color descriptions vary between older comments; identify the buff you actually received instead of trusting color alone.",
        stepCount = 6,
        waypoints = {
            { mapID = 207, x = 0.578, y = 0.13, step = 2, label = "Gorsik - Fungal Fury daily" },
            { mapID = 207, x = 0.687, y = 0.415, step = 3, label = "Shrinkshroom search area" },
            { mapID = 207, x = 0.74, y = 0.39, step = 3, label = "Shuffletruffle search area" },
