    [5451] = {
        achievementId = 5451,
        name = "Consumed by Nightmare",
        category = "Quests",
        sourceType = "Achievement",
        source = "Consumed by Nightmare",
        difficulty = "easy",
        difficultyReason = "Finish a scripted section of the Twilight Highlands campaign.",
        acquisition = "Difficulty: Easy - Finish a scripted section of the Twilight Highlands campaign.\n\n1. Start your faction's Twilight Highlands introduction and follow its campaign toward the Earthen Ring and the Maw of Madness. Use the Fading into Twilight guide if the zone has no quests; flying directly into Iso'rath does not unlock the storyline.\n\n2. At the Earthen Ring hub, begin Torn Ground and follow the offered assault into Iso'rath's Maw. Complete the Nightmare / Unbroken sequence and its rescue objectives. Follow the NPC and vehicle prompts when swallowed; the apparent deaths and the Thrall/Deathwing vision are scripted parts of the story.\n\n3. Finish the escape from Iso'rath's Maw and turn in the follow-up. Check Consumed by Nightmare before leaving the northern quest hub. It does not require killing an outdoor Deathwing spawn or completing the Dragon Soul raid.",
        stepCount = 3,
        waypoints = { { mapID = 241, x = 0.51, y = 0.11, step = 2, label = "Maw of Madness - Iso'rath campaign area" } },
        sources = {
            "https://www.wowhead.com/achievement=5451#comments:id=1217783",
            "https://www.wowhead.com/achievement=5451#comments:id=1367816",
            "https://www.wowhead.com/achievement=5451#comments:id=1455282",
        },
        reviewedAt = "2026-11-10",
        wowheadUrl = "https://www.wowhead.com/achievement=5451",
        sourceURL = "https://www.wowhead.com/achievement=5451#comments",
    },
    [5452] = {
        achievementId = 5452,
        name = "Visions of Vashj'ir Past",
        category = "Quests",
        sourceType = "Achievement",
        source = "Visions of Vashj'ir Past",
        difficulty = "medium",
        difficultyReason = "Three linked Battlemaiden vehicle stories within the Vashj'ir campaign.",
        acquisition = "Difficulty: Medium - Three linked Battlemaiden vehicle stories within the Vashj'ir campaign.\n\n1. Begin Vashj'ir through Call of Duty, Sea Legs and the Kelp'thar Forest quest chain. Continue Across the Great Divide into the Shimmering Expanse, then complete the Silver Tide Hollow and Nespirah rescue story; later visions depend on these earlier quests.\n\n2. Complete Upon the Scene of Battle and Visions of the Past: The Invasion of Vashj'ir. Use the supplied blade/quest interaction to become the Naz'jar Battlemaiden, follow the vehicle's objectives and finish the vision through Not Soon Forgotten.\n\n3. Back in the present, complete Looking Forward and the next naga-assault quests through Visions of the Past: The Slaughter of Biel'aran Ridge. Finish its Battlemaiden quests through The Culmination of Our Efforts; do not leave after merely entering the vision.\n\n4. Continue Losing Ground, Desperate Plan, Come Prepared, Unfurling Plan, Hostile Waters and Honor and Privilege. Follow the next call into Visions of the Past: Rise from the Deep and finish through Final Judgement. If Hexascrub appears to have no follow-up, look for newly arrived Jorlan Trueblade rather than returning to a previous hub.\n\n5. Check all THREE vision criteria. These take place in different phases of the Shimmering Expanse: an ordinary visit to the same ruins outside the quest vehicle is not the vision. Turn in each available quest before expecting the next phase to appear.",
        stepCount = 5,
        waypoints = {
            { mapID = 201, x = 0.4, y = 0.3, step = 1, label = "Kelp'thar Forest - start the underwater campaign" },
            { mapID = 205, x = 0.5, y = 0.41200000000000003, step = 1, label = "Silver Tide Hollow - continue the campaign" },
            { mapID = 205, x = 0.505, y = 0.764, step = 3, label = "Biel'aran Ridge - follow the active vision quest" },
        },
        areaMaps = { 205 },
        sources = {
            "https://www.wowhead.com/achievement=5452#comments:id=1417214",
            "https://www.wowhead.com/achievement=5452#comments:id=1974555",
        },
        reviewedAt = "2026-11-10",
        wowheadUrl = "https://www.wowhead.com/achievement=5452",
        sourceURL = "https://www.wowhead.com/achievement=5452#comments",
    },
    [5453] = {
        achievementId = 5453,
        name = "Ghosts in the Dark",
        category = "Quests",
        sourceType = "Achievement",
        source = "Ghosts in the Dark",
        difficulty = "easy",
        difficultyReason = "An Alliance-only hidden quest in the earlier Darkshore phase.",
        acquisition = "Difficulty: Easy - An Alliance-only hidden quest in the earlier Darkshore phase.\n\n1. Use an ALLIANCE character. If Darkshore is in its Battle for Azeroth warfront phase, speak to Zidormi around 48.8,24.4 and return to the earlier Darkshore. A Hydrath-filled whirlpool in the newer phase is not the required event.\n\n2. Jump into the Maw of the Void, the large northern whirlpool. It transports you into an underground cavern. Pass the friendly Cenarion druid and climb the bank, clearing the undead on the path.\n\n3. Defeat the demon hunter Telarius Voidstrider and loot the Writings of the Dark Herald quest starter. Use it, then speak to the druid for transport out of the cave.\n\n4. Turn the quest in to Ranger Glynda Nal'Shea in Lor'danel around 50,19 to receive the achievement. Horde can enter the cave but cannot earn this Alliance achievement. If the druid is hostile because of Cenarion Circle reputation, use your hearthstone to exit and repair that reputation separately.",
        stepCount = 4,
