    [5454] = {
        achievementId = 5454,
        name = "Joy Ride",
        category = "Quests",
        sourceType = "Achievement",
        source = "Joy Ride",
        difficulty = "easy",
        difficultyReason = "One uninterrupted full-length Rocketway trip on a Horde character.",
        acquisition = "Difficulty: Easy - One uninterrupted full-length Rocketway trip on a Horde character.\n\n1. Use a HORDE character and visit the northern Rocketway tower in Azshara around 66,20. Take the side elevator to the platform and speak to the Bilgewater Rocket-jockey, not the ordinary flight master.\n\n2. Choose Southern Rocketway Terminus, the full trip to the far end around 51,75. A short ride to an intermediate station does not cover the whole Rocketway.\n\n3. Stay on the rocket until it lands. It drives itself; no steering or previously discovered flight paths are needed. Check credit at the terminus. Alliance characters cannot use the hostile Rocket-jockey for this Horde-only achievement.",
        stepCount = 3,
        waypoints = {
            { mapID = 76, x = 0.66, y = 0.2, step = 1, label = "Northern Rocketway Terminus - elevator and jockey" },
            { mapID = 76, x = 0.51, y = 0.75, step = 3, label = "Southern Rocketway Terminus - ride to the end" },
        },
        faction = "Horde",
