    },
    [5455] = {
        achievementId = 5455,
        name = "Got My Mind On My Money",
        category = "General",
        sourceType = "Achievement",
        source = "Got My Mind On My Money",
        difficulty = "medium",
        difficultyReason = "Accumulate 50000 gold in actual loot, not income from selling items.",
        acquisition = "Difficulty: Medium - Accumulate 50000 gold in actual loot, not income from selling items.\n\n1. Track the achievement's LOOTED-GOLD counter before beginning. Your wallet balance is not the requirement: gold from the Auction House, vendoring, mail or ordinary quest-reward payments does not substitute for looted coin.\n\n2. Combine this with old raid, dungeon, mount or reputation farming that you can comfortably clear. For a Cataclysm route, enter Blackwing Descent above Blackrock Mountain or Firelands in outdoor Mount Hyjal, clear the encounters and loot EVERY available corpse, including trash.\n\n3. Check the counter after looting a boss and continue clearing unlocked instances. Sell or store unwanted items to keep bags usable, but count only the coin credited when you loot. Old comments' Cataclysm-era gold-per-run estimates and now-obsolete class soloing instructions do not describe current payouts.\n\n4. Repeat on available lockouts until 50000 looted gold is recorded. Raid bosses obey their instance lockouts; entering an already-cleared saved instance or resetting without eligible fresh loot does not create another payout. Check the counter before deciding whether to continue on an alt.",
        stepCount = 4,
        waypoints = {
