    [5469] = {
        achievementId = 5469,
        name = "Diggerer",
        category = "Professions",
        sourceType = "Achievement",
        source = "Diggerer",
        difficulty = "medium",
        difficultyReason = "Complete many common projects across cultures; duplicates are unreliable for the unique-project target.",
        acquisition = "Difficulty: Medium - Complete many common projects across cultures; duplicates are unreliable for the unique-project target.\n\n1. Learn Archaeology from Harrison Jones in Stormwind's library (85.6, 25.8) or Belloc Brightblade in Orgrimmar (49.0, 70.6). Enable Archaeology dig sites on the world map. Dig sites are personal and move as YOU finish them; another player's route does not determine your active sites.\n\n2. At an active dig site, stand inside its highlighted boundary and use Survey. Follow the instrument's direction: red means far away, yellow closer, green nearby. Survey again until the fragment object appears, then LOOT it. Continue until the site disappears and a replacement spawns. Clearing unwanted races also frees slots for the race you need.\n\n3. Open Archaeology, select the race whose fragments you collected, and complete its CURRENT research project when you have enough fragments. Insert matching keystones where the project has sockets to reduce its cost. The next project is random: you cannot select an unsolved artifact directly.\n\n4. Finish 50 DIFFERENT COMMON projects and inspect the completed-artifact journal and achievement counter. Rare blue projects advance the rare achievements instead. The written requirement is unique projects; do not plan the route around a temporary report that duplicate commons counted after a bug fix.\n\n5. When one culture repeatedly offers artifacts already in your journal, move to cultures with missing commons. Eastern Kingdoms supplies Dwarf and Troll; Kalimdor supplies Night Elf and Fossil; Outland supplies Orc and Draenei; Northrend supplies Nerubian and Vrykul. Tol'vir and later-expansion cultures add more choices.\n\n6. Continue until the live counter reaches 50. The older progress-reset issue was reported fixed around Midnight prepatch; current collection comments confirm renewed progress. If your own journal fails to retain a solve, check it before committing to another long session.",
        stepCount = 6,
        waypoints = {
            { mapID = 84, x = 0.856, y = 0.258, step = 1, label = "Harrison Jones - Archaeology trainer" },
            { mapID = 85, x = 0.49, y = 0.706, step = 1, label = "Belloc Brightblade - Archaeology trainer" },
        },
        areaMaps = { 13, 12, 101, 113 },
        sources = {
            "https://www.wowhead.com/achievement=5315#comments:id=1299649",
            "https://www.wowhead.com/achievement=5470#comments:id=1222281",
            "https://www.wowhead.com/achievement=5470#comments:id=6346617",
