    [5471] = {
        achievementId = 5471,
        name = "Iron Chef",
        category = "Professions",
        sourceType = "Achievement",
        source = "Iron Chef",
        difficulty = "medium",
        difficultyReason = "Learn two hundred Cooking recipes across available expansion categories.",
        acquisition = "Difficulty: Medium - Learn two hundred Cooking recipes across available expansion categories.\n\n1. Train Cooking and inspect its learned recipe count. This is a LEARNED-recipes achievement, so buying finished food and cooking two hundred copies of one recipe do not advance the target.\n\n2. Learn the inexpensive unlearned trainer recipes in each expansion's Cooking category. Begin with Classic trainers in the capitals and the Outland/Northrend trainers, then add Pandaria and later expansion trainers. Use the profession window's Unlearned filter to choose recipes you can actually learn.\n\n3. Buy missing ordinary recipes from cooking-supply vendors and the Auction House. Alliance can visit Kendor Kabonka upstairs in the Pig and Whistle (76.0, 53.2 in Stormwind) for many Classic vendor recipes; Horde can obtain tradable opposite-faction recipes through the Auction House. Learn the recipe item after buying it.\n\n4. Add Cataclysm and Northrend recipes sold for Epicurean's Awards, earned from their separate daily hubs. Seasonal Cooking vendors and reputation recipes can fill gaps, but retired Dirge's Chimaerok Chops and Rogue-only Thistle Tea are not necessary in modern Retail.\n\n5. Keep learning DIFFERENT available recipes until the live counter reaches TWO HUNDRED. Old comments claiming a new character is capped below 200 describe Cataclysm's original recipe pool; later expansions supply many alternatives.",
        stepCount = 5,
        waypoints = {
            { mapID = 84, x = 0.76, y = 0.532, step = 3, label = "Kendor Kabonka - many Classic cooking recipes" },
            { mapID = 85, x = 0.322, y = 0.696, step = 2, label = "Zamja - Cooking trainer" },
            { mapID = 84, x = 0.768, y = 0.536, step = 2, label = "Stephen Ryback - Cooking trainer" },
        },
        areaMaps = { 111, 125, 376 },
        sources = {
            "https://www.wowhead.com/achievement=5471#comments:id=1351984",
