    [5472] = {
        achievementId = 5472,
        name = "The Cataclysmic Gourmet (15 recipes)",
        category = "Professions",
        sourceType = "Achievement",
        source = "The Cataclysmic Gourmet (15 recipes)",
        difficulty = "medium",
        difficultyReason = "Learn and personally cook many different Cataclysm recipes; awards take repeated daily visits.",
        acquisition = "Difficulty: Medium - Learn and personally cook many different Cataclysm recipes; awards take repeated daily visits.\n\n1. Learn Cataclysm Cooking and track the achievement's recipe checklist. You must personally COOK 15 DIFFERENT listed recipes. Learning recipes alone, eating the food or buying another player's finished dishes does not replace crafting them.\n\n2. Earn Epicurean's Awards from capital Cooking dailies and the separate Northrend Dalaran Cooking daily. Spend them at the capital sous-chef vendors, such as Jon Casper near Robby Flay in Stormwind or Shazdar near Marogg in Orgrimmar. The vendors sell the Cataclysm recipes; Blackened Surprise and Darkbrew Lager are trainer recipes.\n\n3. Start with simple listed dishes: Blackened Surprise uses Toughened Flesh; Broiled Mountain Trout uses Mountain Trout; Lightly Fried Lurker and Lurker Lunch use Striped Lurker; Lavascale Fillet and Lavascale Minestrone use Lavascale Catfish. Cook each DIFFERENT recipe once and check its criterion.\n\n4. Fish or buy Cataclysm ingredients. Hyjal supplies Mountain Trout and Striped Lurker; original Uldum's river supplies Blackbelly Mudfish, Lavascale Catfish and Sharptooth; Twilight Highlands supplies Highland Guppy inland and Algaefin Rockfish/Deepsea Sagefish on its coast; Tol Barad's coast supplies Fathom Eel. Buying raw materials is valid.\n\n5. For meat dishes, gather or buy Crocolisk Tail in Uldum, Dragon Flank in Twilight Highlands/Deepholm, Delicate Wing from Uldum birds, Basilisk Liver from Deepholm basilisks, and Snake Eye/Monstrous Claw/Blood Shrimp from Vashj'ir creatures and their clams. Use the recipe's current material quantities; an old shopping list counted recipe uses rather than all actual material amounts.\n\n6. Add the vendor-ingredient recipes: Chocolate Cookie needs Simple Flour and Cocoa Beans; Starfire Espresso uses Cocoa Beans and Refreshing Spring Water; Highland Spirits uses Highland Pomegranate and water; South Island Iced Tea uses Tropical Sunfruit and water; Darkbrew Lager uses Dwarven Stout and Badlands Bourbon. Fortune Cookie also needs a Mysterious Fortune Card from Inscription or the Auction House.\n\n7. Cook missing recipes until the counter reaches 15. The checklist offers THIRTY-TWO choices, so the thirty-recipe tier can skip BOTH guild-unlocked feasts. Feathered Lure is available again; the old removal warning is obsolete. Eat your completed food and drinks afterward if also pursuing Cataclysmically Delicious and Drown Your Sorrows.",
        stepCount = 7,
        waypoints = {
            { mapID = 84, x = 0.506, y = 0.716, step = 2, label = "Robby Flay / Jon Casper - awards and recipes" },
            { mapID = 85, x = 0.5660000000000001, y = 0.626, step = 2, label = "Marogg / Shazdar - awards and recipes" },
            { mapID = 249, x = 0.62, y = 0.79, step = 5, label = "Uldum serpents - Toughened Flesh" },
            { mapID = 249, x = 0.664, y = 0.604, step = 5, label = "Uldum carrion birds - Delicate Wing" },
            {
                mapID = 249,
                x = 0.7020000000000001,
                y = 0.6759999999999999,
                step = 5,
                label = "Uldum carrion birds - alternative wing farm",
            },
        },
