    [5480] = {
        achievementId = 5480,
        name = "Preparing for Disaster",
        category = "Professions",
        sourceType = "Achievement",
        source = "Preparing for Disaster",
        difficulty = "medium",
        difficultyReason = "Five hundred personal crafts and the Tailoring recipe unlock; still obtainable after First Aid's removal.",
        acquisition = "Difficulty: Medium - Five hundred personal crafts and the Tailoring recipe unlock; still obtainable after First Aid's removal.\n\n1. Use a character with TAILORING and learn its Cataclysm category. First Aid is gone, but this crafting achievement is still obtainable through Tailoring. Track the achievement before making bandages; buying already finished Dense Embersilk Bandages is not a personal craft.\n\n2. Visit Angela Leifeld inside Stormwind Cathedral (52.0,45.6), or Mender Jessara behind the Orgrimmar Embassy (38.2,86.2), for the bandage recipes. Level Cataclysm Tailoring until Dense Embersilk Bandage is offered; its current spell tooltip lists Cataclysm Tailoring 75. Lower bandage recipes can raise skill without using the volatile reagents required by many ordinary Tailoring recipes. Keep your Heavy Embersilk Bandages for conversion afterward.\n\n3. For the direct Dense recipe, reserve THREE Embersilk Cloth per remaining craft: from zero credit, 500 crafts require 1,500 cloth AFTER any extra cloth spent leveling. Buy cloth or farm eligible Cataclysm humanoids. Do not confuse the icon's Heavy bandage with the required DENSE output.\n\n4. Alternatively, learn Field Bandage: Dense Embersilk and convert TWO Heavy Embersilk Bandages into ONE Dense. These conversions also count. Use Heavy bandages left from leveling or compare their Auction House cost with three raw cloth; crafting the Heavy inputs yourself uses four cloth per final Dense and is less cloth-efficient.\n\n5. Make one Dense, check the counter, then craft the remaining total on the same character until it reaches FIVE HUNDRED. Keep free bag slots, selling or banking completed bandages between queues if needed. Heavy bandage crafts alone do not add credit; the output must be Dense Embersilk Bandage. Reports that this became unobtainable with First Aid were superseded by Retail Tailoring confirmations.",
        stepCount = 5,
        waypoints = {
            { mapID = 84, x = 0.52, y = 0.456, step = 2, label = "Angela Leifeld - bandage trainer inside Cathedral" },
            { mapID = 85, x = 0.382, y = 0.862, step = 2, label = "Mender Jessara - bandage trainer behind Embassy" },
        },
