    [5481] = {
        achievementId = 5481,
        name = "Wildhammer Tour of Duty",
        category = "Quests",
        sourceType = "Achievement",
        source = "Wildhammer Tour of Duty",
        difficulty = "easy",
        difficultyReason = "A short faction-specific named-enemy circuit.",
        acquisition = "Difficulty: Easy - A short faction-specific named-enemy circuit.\n\n1. Use a Alliance character and progress the Twilight Highlands introduction through your faction's Thundermar/Bloodgulch campaign. Track the achievement; the Horde checklist has sometimes been hidden in the UI, so use the named targets below as well.\n\n2. Search the Thundermar Ruins and kill: Warlord Halthar; Black Recluse - cellar entrance; Karkrog the Exterminator; Korthalon the Black - cellar entrance. The map pins distinguish outside patrols from basement entrances. Enter the buildings and go downstairs for cellar targets rather than searching only the roof-level map position.\n\n3. Check each kill criterion. Wait for a missing named enemy to respawn, and move along its patrol if its pin is empty. The factions have different lists; killing only the shared spider and Korthalon does not finish either version.",
        stepCount = 3,
