    [5483] = {
        achievementId = 5483,
        name = "Bounce",
        category = "Quests",
        sourceType = "Achievement",
        source = "Bounce",
        difficulty = "medium",
        difficultyReason = "Twenty consecutive controlled trampoline landings.",
        acquisition = "Difficulty: Medium - Twenty consecutive controlled trampoline landings.\n\n1. Find the trampoline west of the Grove of Aessina in Mount Hyjal's Whistling Grove, around 13.54,32.17. Track Bounce before stepping onto its center; no active bear-rescue daily is required just to use it.\n\n2. Use an overhead camera. As each bounce throws you outward, turn your character toward the CENTER in midair and move forward on landing to get back before the next bounce impulse.\n\n3. Repeat for TWENTY consecutive bounces, watching the tracked count. If you land too far away or miss a launch, it resets. A ground mount can help reposition faster; avoid accidentally taking off on a flying mount.\n\n4. Check credit at twenty and move off the trampoline. Busy crowds can make the individual bounce effects difficult to read, so use your own counter and landings rather than another player's dust effect.",
        stepCount = 4,
        waypoints = { { mapID = 198, x = 0.1354, y = 0.32170000000000004, step = 1, label = "Whistling Grove - trampoline" } },
