    [5511] = {
        achievementId = 5511,
        name = "It's Always in the Last Place You Look",
        category = "Professions",
        sourceType = "Achievement",
        source = "It's Always in the Last Place You Look",
        difficulty = "medium",
        difficultyReason = "Finish one artifact from each of the nine original cultures.",
        acquisition = "Difficulty: Medium - Finish one artifact from each of the nine original cultures.\n\n1. Learn Archaeology from Harrison Jones in Stormwind's library (85.6, 25.8) or Belloc Brightblade in Orgrimmar (49.0, 70.6). Enable Archaeology dig sites on the world map. Dig sites are personal and move as YOU finish them; another player's route does not determine your active sites.\n\n2. Raise Archaeology to 450 so all nine required cultures can appear. Fragments alone are insufficient: complete at least ONE research solve from each required culture.\n\n3. In Eastern Kingdoms, complete a Dwarf, Troll and Fossil artifact. In Kalimdor, complete a Night Elf artifact and use original Uldum for a Tol'vir artifact; ask Zidormi near 56.0, 35.1 if an assault phase interferes.\n\n4. In OUTLAND, survey and solve BOTH an Orc and a Draenei project. These use the original continent's archaeology, not Draenor archaeology.\n\n5. In Northrend, survey and solve BOTH a Vrykul and a Nerubian project. Complete unwanted sites to replace them when the culture you need is absent.\n\n6. Check all nine criteria after the solves. Pandaren, Mogu, Mantid and later races are not required substitutes. A May 2026 reply confirms the previously broken Draenei criterion was awarding progress again.",
        stepCount = 6,
        waypoints = {
            { mapID = 84, x = 0.856, y = 0.258, step = 1, label = "Harrison Jones - Archaeology trainer" },
            { mapID = 85, x = 0.49, y = 0.706, step = 1, label = "Belloc Brightblade - Archaeology trainer" },
            { mapID = 249, x = 0.56, y = 0.35100000000000003, step = 3, label = "Zidormi - original Tol'vir archaeology" },
        },
        areaMaps = { 13, 12, 101, 113 },
