    [5518] = {
        achievementId = 5518,
        name = "Stood in the Fire",
        category = "Exploration",
        sourceType = "Achievement",
        source = "Stood in the Fire",
        difficulty = "medium",
        difficultyReason = "Reach Deathwing in Dragon Soul and deliberately die during his encounter.",
        acquisition = "Difficulty: Medium - Reach Deathwing in Dragon Soul and deliberately die during his encounter.\n\n1. Enter Dragon Soul in the Caverns of Time in Tanaris. Use the raid's existing clear guides to reach Spine or Madness of Deathwing. Deathwing's old random outdoor zone attacks are no longer the dependable acquisition route.\n\n2. At Spine, let a completed roll throw you off while unanchored and die. Alternatively, at Madness, begin the encounter with Thrall, attack Deathwing once and die by falling from a platform. Make sure combat has actually begun before attempting the death.\n\n3. Check the achievement after dying, release and return as the raid permits. Do not kill Deathwing first if you are saving this character's eligible encounter for the death. Older comments and later Retail confirmations establish the raid route; a normal unrelated death in Tanaris does not count.",
        stepCount = 3,
        waypoints = { { mapID = 71, x = 0.644, y = 0.5, step = 1, label = "Caverns of Time - Dragon Soul portal inside" } },
        areaMaps = { 409, 415 },
        sources = {
            "https://www.wowhead.com/achievement=5518#comments:id=1141069",
            "https://www.wowhead.com/achievement=5518#comments:id=5534379",
            "https://www.wowhead.com/achievement=5518#comments:id=5602457",
        },
        reviewedAt = "2026-11-10",
        wowheadUrl = "https://www.wowhead.com/achievement=5518",
        sourceURL = "https://www.wowhead.com/achievement=5518#comments",
    },
    [5546] = {
        achievementId = 5546,
        name = "Glutton for Icy Punishment",
        category = "Quests",
        sourceType = "Achievement",
        source = "Glutton for Icy Punishment",
        difficulty = "medium",
        difficultyReason = "Avoid the trial hazards while building an uninterrupted counter.",
        acquisition = "Difficulty: Medium - Avoid the trial hazards while building an uninterrupted counter.\n\n1. Go to Archmage Xylem's Arcane Pinnacle in northern Azshara around 55.98,12.16. Both factions can attempt these achievements, including after finishing the apprentice quests. Use the corresponding crystal AND its opened portal, or travel directly to the trial area shown on the guide map.\n\n2. Enter the Trial of Frost around 62.2,21.1. Track the achievement before starting so a failed attempt is visible.\n\n3. Collect TWENTY small ice orbs without taking damage. Avoid the rotating frost streams around the large orbs and the blue ground platforms that launch ice spikes. Follow the OUTER rim and pause in safe pockets while a stream passes; you do not need to race through the center.\n\n4. With flying available, hover over the danger and dip down for a small orb only when the stream is well clear, then rise again. Use the tracked achievement's counter: the quest's displayed count and a stale buff icon can differ from your uninterrupted achievement progress.\n\n5. When the required uninterrupted count is credited, check the achievement before leaving the trial. Damage resets the attempt; ordinary completion of the apprentice quest is not proof that its special avoidance achievement succeeded.",
        stepCount = 5,
        waypoints = {
            { mapID = 76, x = 0.5598, y = 0.1216, step = 1, label = "Arcane Pinnacle - trial crystals and portals" },
            { mapID = 76, x = 0.622, y = 0.21100000000000002, step = 2, label = "Trial of Frost" },
        },
        sources = {
            "https://www.wowhead.com/achievement=5546#comments:id=1176945",
            "https://www.wowhead.com/achievement=5546#comments:id=1180686",
            "https://www.wowhead.com/achievement=5546#comments:id=5453236",
        },
        reviewedAt = "2026-11-10",
        wowheadUrl = "https://www.wowhead.com/achievement=5546",
        sourceURL = "https://www.wowhead.com/achievement=5546#comments",
