    [5552] = {
        achievementId = 5552,
        name = "Double Jeopardy",
        category = "PvP",
        sourceType = "Achievement",
        source = "Double Jeopardy",
        difficulty = "hard",
        difficultyReason = "Win after your team has been behind 0-2.",
        acquisition = "Difficulty: Hard - Win after your team has been behind 0-2.\n\n1. Queue for TWIN PEAKS through the PvP panel, selecting the specific battleground when available. Track this achievement before the gates open. Warsong Gulch has a similar flag mode but does not award Twin Peaks objectives.\n\n2. In a match where the opponents have taken a TWO-CAPTURE LEAD while your team has zero, keep playing and organize a comeback: escort your carrier and commit defenders to returning the enemy-carried flag.\n\n3. Win from that state. A normal 3-2 comeback qualifies; a tied 2-2 finish can also be a win under the match's last-capture tiebreak rules. The result must actually declare YOUR team the winner.\n\n4. Check credit at the result. Do not rely on the old Mercenary-mode score inversion: replies report it fixed, and a 2026 comment reports no credit under Mercenary Contract. Use the version matching your character's faction and an ordinary eligible match.",
        stepCount = 4,
        waypoints = {},
        areaMaps = { 206 },
        sources = {
            "https://www.wowhead.com/achievement=5552#comments:id=1490660",
            "https://www.wowhead.com/achievement=5552#comments:id=6403155",
        },
        reviewedAt = "2026-11-10",
        wowheadUrl = "https://www.wowhead.com/achievement=5552",
        sourceURL = "https://www.wowhead.com/achievement=5552#comments",
    },
    [5718] = {
        achievementId = 5718,
        name = "Just Another Day in Tol Barad",
        category = "Quests",
        sourceType = "Achievement",
        source = "Just Another Day in Tol Barad",
        difficulty = "hard",
        difficultyReason = "Complete every unique daily variant; empty shards can prevent rotations.",
        acquisition = "Difficulty: Hard - Complete every unique daily variant; empty shards can prevent rotations.\n\n1. Use one Alliance character and track the achievement's individual quest names. Portal to Tol Barad Peninsula and visit your faction's camp. A 2026 Retail report says completing missing variants on an alt did NOT merge the checklist despite its account-wide label, so finish the checklist on the same character.\n\n2. PENINSULA OVERLOOK / SHIPYARD: accept available camp quests before traveling. At Largo's Overlook in the east complete Ghostbuster, Cannonball! and Taking the Overlook Back when each appears; at western Wellson Shipyard complete WANTED: Foreman Wellson, Watch Out For Splinters! and Bombs Away!. Only the current random choices are offered each reset; repeated completions of one do not replace another.\n\n3. PENINSULA NORTH/WEST: Rustberg Village supplies Not The Friendliest Town and Teach A Man To Fish... Or Steal. Farson Hold supplies Walk A Mile In Their Shoes, Leave No Weapon Behind and Claiming The Keep. Cape of Lost Hope supplies Captain P. Harris, Rattling Their Cages, Shark Tank and Boosting Morale. Finish the objective and hand in each offered variant.\n\n4. PENINSULA SOUTH/CENTRE: The Darkwood supplies A Sticky Task and Thinning the Brood; The Restless Front supplies Finish The Job and Magnets, How Do They Work?; Forgotten Hill supplies First Lieutenant Connor, Salvaging the Remains and The Forgotten. Return to the CAMP for hand-ins and compare your missing names with the live checklist.\n\n5. SOUTHERN ISLAND: when your faction controls Tol Barad, cross the southern bridge and take the central hub's A Huge Problem (kill Problim), Swamp Bait (crocolisk hides) and The Leftovers (enemy infantry at the three keeps). These are separate from the Peninsula quests.\n\n6. OPEN PRISON: take all three quests from the second central questgiver and enter the prison named by that group. D-Block gives D-Block, Cursed Shackles and Svarnos; Cursed Depths gives Clearing the Depths, Learning From The Past and The Imprisoned Archmage; The Hole gives Food From Below, Prison Revolt and The Warden. Finish the kill, ground-item and named-boss objectives inside the OPEN prison, then return to the central hub. Each group must eventually rotate into availability.\n\n7. IF THE SAME QUESTS REPEAT EVERY DAY: be physically present in the PENINSULA just BEFORE your region's daily reset and remain through it, then inspect the questgivers. Recent 2026 reports say this lets an otherwise recycled empty shard rotate its quests. Use the region's actual daily-reset time, not an old comment's local-clock conversion. Logging out overnight or merely toggling War Mode is not a guaranteed rotation.\n\n8. Inspect available names BEFORE accepting mutually exclusive variants. If checking a different War Mode/realm shard, use the SAME character and matching phase; a second shard can have another draw, but may also offer the same default set. Complete missing hand-ins and recheck the entire live checklist, including all three prison groups. Temporary rotation problems alone are not proof the achievement is retired.",
        stepCount = 8,
        waypoints = {
            { mapID = 245, x = 0.73, y = 0.6, step = 1, label = "Alliance camp - accept and hand in dailies" },
            { mapID = 245, x = 0.785, y = 0.45, step = 2, label = "Largo's Overlook - quest objective area" },
            {
                mapID = 245,
                x = 0.272,
                y = 0.47600000000000003,
                step = 2,
                label = "Wellson Shipyard - lumber / undead objective area",
            },
            { mapID = 245, x = 0.675, y = 0.32, step = 3, label = "Rustberg Village" },
            { mapID = 245, x = 0.36, y = 0.28, step = 3, label = "Farson Hold - keep / basement escort" },
            { mapID = 245, x = 0.47, y = 0.2, step = 3, label = "Cape of Lost Hope" },
            { mapID = 245, x = 0.5379999999999999, y = 0.522, step = 4, label = "The Darkwood - spiders" },
