    [5723] = {
        achievementId = 5723,
        name = "50 Exalted Reputations",
        category = "Reputation",
        sourceType = "Achievement",
        source = "50 Exalted Reputations",
        difficulty = "hard",
        difficultyReason = "Many separate reputation grinds, including time-gated factions.",
        acquisition = "Difficulty: Hard - Many separate reputation grinds, including time-gated factions.\n\n1. Track 50 Exalted Reputations and check its live distinct-faction total. Make a list of factions already close to Exalted; another copy of the same faction on an alt is not a new unique reputation. Use the current tracker when combining Warband progress.\n\n2. Fill quick dungeon reputations: wear city tabards for eligible city reputation, use the four original Northrend championing tabards, and use the six Cataclysm championing factions. At Friendly buy the matching tabard, equip it, and verify the kill log awards the intended faction before repeating a dungeon.\n\n3. Add original Outland dungeon factions through their own dungeons: Cenarion Expedition in Coilfang, Lower City in Auchindoun, Sha'tar in Tempest Keep dungeons, and Keepers of Time in the Caverns of Time. A Cataclysm tabard is not a substitute for these factions' default dungeon reputation.\n\n4. Use raid clears for Hydraxian Waterlords, Brood of Nozdormu, Violet Eye, Ashtongue, Ashen Verdict and Avengers of Hyjal. Observe each faction's trash cap and finish the remaining bar with eligible bosses or its required turn-ins. Combine these with your weekly mount and legendary routes.\n\n5. Fill remaining slots with currently available daily factions, such as Ramkahen, Therazane, Tol Barad, Kalu'ak and later-expansion factions. Keep their hand-in schedule and actual reputation bars visible; retired factions and an old mutually exclusive counterpart need not be part of the route.\n\n6. Continue until the live counter reaches 50. Rank/renown displays from later systems do not automatically mean that an Exalted criterion counted; verify each planned addition rather than assuming every reputation UI bar contributes.",
        stepCount = 6,
        waypoints = {
            { mapID = 249, x = 0.54, y = 0.332, step = 2, label = "Ramkahen - championing tabard" },
            { mapID = 207, x = 0.568, y = 0.132, step = 2, label = "Therazane - tabard after campaign" },
            { mapID = 118, x = 0.535, y = 0.855, step = 4, label = "ICC - Ashen Verdict" },
            { mapID = 198, x = 0.47200000000000003, y = 0.7809999999999999, step = 4, label = "Firelands - Avengers of Hyjal" },
        },
        sources = { "https://www.wowhead.com/achievement=5374#comments", "https://www.wowhead.com/achievement=5723#comments" },
        reviewedAt = "2026-11-05",
        wowheadUrl = "https://www.wowhead.com/achievement=5723",
        sourceURL = "https://www.wowhead.com/achievement=5723#comments",
    },
}

