        [5444] = {
            acquisition = "1. Go to Fuselight in Badlands (64.3, 38.0). Finish Garyanne Fleezlebop's When the Going Gets Tough, Cheat, then accept It's Goat Time, Baby for the Billy Goat Blaster.\n2. If you already turned in the quest, buy Billy Goat Blaster DX from Gina Gotgoods nearby (64.25, 37.46). Completing the quest does not lock you out.\n3. Put the blaster on your action bar. An optional targeting macro is:\n/target Billy Goat\n/use Billy Goat Blaster\nFor the purchased version, replace the last line with /use Billy Goat Blaster DX.\n4. Locate a route between 12 Billy Goats before firing. Stay mounted, move close to each goat and blast 12 within 60 seconds of your first hit.\n5. If using the quest blaster, wait for achievement credit before handing in the quest. Retry the timed run if necessary.",
            sourceType = "Achievement",
            source = "Garyanne Fleezlebop / Gina Gotgoods",
            sourceURL = "https://www.wowhead.com/achievement=5444#comments",
            waypoints = {
                "/way #15 64.3 38.0 Garyanne Fleezlebop - goat quest chain",
                "/way #15 64.25 37.46 Gina Gotgoods - Billy Goat Blaster DX",
            },
            walkthrough = walkthroughs[5444],
        },
