    research = {
        notes = {
            ["Data/Expansions/Cataclysm/AchievementBattlegroundGuides.lua"] = "-- Retail objective guides. These are not the separate rated-win or rating-title counters.",
            ["Data/Expansions/Cataclysm/AchievementCollectionGuides.lua"] = "-- English Retail collection and legendary guides. Reviewed 2026-11-05.\n-- Existing mount/pet routes were reviewed against these achievement comments.\n-- Preserve their detailed current routes, including the complete figurine map.",
            ["Data/Expansions/Cataclysm/AchievementDungeonGuides.lua"] = "-- English Retail walkthroughs, manually reconciled with Wowhead comments and\n-- replies. Reviewed 2026-11-04. Difficulty describes the achievement mechanic,\n-- including damage control and travel, rather than the original level-85 fight.\n-- NPC coordinates use Retail Wowhead g_mapperData. Floor numbers are resolved\n-- with Retail UiMapGroupMember, not confused with Wowhead's zone IDs.\n-- Preferred numbered profit guide: 3217997, including all three public replies.\n-- The Midnight report 6461312 updates the damage-control method; its measured\n-- 47% hit is character-specific, not a promised damage value.\n-- Preferred numbered profit guide 2063513, with both complete replies read.\n-- Retain its jump/burst approach, but include the cast-based fallback because\n-- both replies report failed instant kills.\n-- Numbered profit guide 1389194 supplies the servant order and charge timing.\n-- Replace its original level-85 shield-burning and gear advice with Retail\n-- damage control; later reports support killing the three servants individually.\n-- Numbered profit guide 1423924: keep gathering spirits, then kill twenty\n-- together. Its obsolete level-85 party composition is unnecessary in Retail.\n-- Normal and Heroic clear pages were read individually. Most have no comments;\n-- retain the useful entrance/script details from the existing mount walkthrough\n-- and the encounter guides above, instead of inventing a profit comment.\n-- Promote the existing detailed 27-step achievement-reward route without\n-- discarding its useful research, restrictions, Midnight updates or map data.",
            ["Data/Expansions/Cataclysm/AchievementExplorationGuides.lua"] = "-- English Retail exploration routes; comments, replies and current criteria reviewed 2026-11-10.",
            ["Data/Expansions/Cataclysm/AchievementFishingFoodGuides.lua"] = "-- Current Retail species checklists and merchant inventories, reviewed 2026-11-10.",
            ["Data/Expansions/Cataclysm/AchievementMilestoneGuides.lua"] = "-- Personal counters, quest arenas and Tol Barad dailies, reviewed 2026-11-10.",
            ["Data/Expansions/Cataclysm/AchievementMoltenFrontGuides.lua"] = "-- Retail outdoor campaign guides, reconciled with comments and replies on 2026-11-10.\n-- Keep the complete, already researched mount route and its numbered locations.",
            ["Data/Expansions/Cataclysm/AchievementOutdoorGuides.lua"] = "-- Retail quest mechanics and outdoor challenges, reviewed 2026-11-10.\n-- Preserve the previously authored escort route and all its underground pins.",
            ["Data/Expansions/Cataclysm/AchievementProfessionGuides.lua"] = "-- Retail professions, manually reconciled with comments and replies, 2026-11-05.\n-- City NPC positions are current Retail g_mapperData. Their shared lockout is\n-- one Cooking AND one Fishing daily per character per day, not one per city.",
            ["Data/Expansions/Cataclysm/AchievementQuestGuides.lua"] = "-- Retail storyline routes. Old quest-count comments are reconciled with current chapter criteria.\n-- Each leg is a manually authored chapter route. Hub pins describe search areas,\n-- not an invented exact position for every NPC in that settlement.",
            ["Data/Expansions/Cataclysm/AchievementRaidGuides.lua"] = "-- Retail raid walkthroughs reviewed 2026-11-04. Numbered profit guides are\n-- reconciled with their replies, recent Retail reports and the existing mount\n-- routes; original level-85 DPS, gear and class requirements are not retained.\n-- Boss positions: current Retail JournalEncounter Map_0/Map_1 and UiMapID.\n-- Each Heroic achievement's own comment list was read; most old comments are\n-- progression-era ability explanations rather than numbered acquisition guides.\n-- Keep the already researched mount routes intact when presenting their actual\n-- achievement IDs. These are full numbered guides, not a pointer to buy a mount.",
            ["Data/Expansions/Cataclysm/AchievementRatedGuides.lua"] = "-- Retail rated PvP, reviewed 2026-11-04. Each rank and victory page's comments\n-- were read. Current achievement records explicitly allow Blitz for RATING\n-- titles; 2026 comments still exclude Blitz from the old VICTORY counters.\n-- Factions were checked in the current Achievement table. Numeric ordering is\n-- misleading: 5338 and 5342 are Horde; 5357 and 5359 are Alliance.",
            ["Data/Expansions/Cataclysm/AchievementReputationGuides.lua"] = "-- Retail faction routes and current phase access, reviewed 2026-11-05.",
        },
    },
